Object.assign(window.EL_CAPSULES, {
  "p6:Oct:1": {"title": "El ocaso de un gigante (1598–1700)", "steps": [{"type": "hook", "kicker": "Historia · Semana 1", "h": "¿Puede caer un imperio donde nunca se ponía el sol?", "scenario": "Imagina un mapa donde España tiene territorios en América, Europa, Asia y África. Parece imposible que algo así se derrumbe... y sin embargo, en poco más de cien años, ocurrió.", "body": "Entre 1598 y 1700 reinaron los llamados <b>Austrias menores</b>: Felipe III, Felipe IV y Carlos II. Bajo su gobierno, el imperio más extenso de la historia empezó a resquebrajarse por dentro. Esta semana vas a construir la línea de tiempo de ese declive."}, {"type": "theory", "kicker": "Historia · Conceptos clave", "h": "Los Austrias menores: tres reyes, un declive", "body": "Se llama <b>Austrias menores</b> a los tres últimos reyes de la dinastía Habsburgo en España: <b>Felipe III</b> (1598-1621), <b>Felipe IV</b> (1621-1665) y <b>Carlos II</b> (1665-1700), apodado \"el Hechizado\" por su débil salud. A diferencia de sus antecesores Carlos I y Felipe II, estos monarcas delegaron el gobierno en validos (como el Conde-Duque de Olivares) y el imperio fue perdiendo fuerza militar, económica y territorial hasta llegar, con Carlos II, a la extinción de la dinastía sin descendencia.", "diagram": "<b>1598</b> Felipe III sube al trono <br><b>1609</b> Expulsión de los moriscos <br><b>1621</b> Felipe IV y el valido Olivares <br><b>1640</b> Rebelión y pérdida de Portugal <br><b>1648</b> Paz de Westfalia: España reconoce la independencia de los Países Bajos <br><b>1665</b> Carlos II, el último Austria <br><b>1700</b> Muerte de Carlos II sin heredero"}, {"type": "quiz", "kicker": "Historia · Ponte a prueba", "h": "¿Qué reyes formaron los Austrias menores?", "q": "¿Cuál de estos grupos de reyes corresponde a los llamados 'Austrias menores'?", "opts": [{"t": "Felipe III, Felipe IV y Carlos II", "ok": true}, {"t": "Carlos I, Felipe II y Felipe III", "ok": false}, {"t": "Felipe IV, Carlos II y Felipe V", "ok": false}, {"t": "Isabel la Católica, Carlos I y Felipe II", "ok": false}], "okMsg": "Exacto. Estos tres reyes gobernaron entre 1598 y 1700, el periodo del gran declive imperial.", "noMsg": "No es correcto. Los Austrias menores son Felipe III, Felipe IV y Carlos II, los tres últimos Habsburgo españoles."}, {"type": "reflect", "kicker": "Historia · Tu turno", "h": "Construye tu línea de tiempo", "body": "Vas a ordenar los acontecimientos clave del declive del Imperio español entre 1598 y 1700, situándolos en su reinado correspondiente.", "prompt": "Dibuja o escribe una línea de tiempo con al menos 6 fechas entre 1598 y 1700 (por ejemplo: subida al trono de cada rey, pérdida de Portugal en 1640, Paz de Westfalia en 1648, muerte de Carlos II en 1700). Para cada fecha, indica en una frase qué ocurrió y bajo qué rey."}]},
  "p6:Oct:2": {"title": "Por qué cae un imperio: causas y efectos", "steps": [{"type": "hook", "kicker": "Historia · Semana 2", "h": "¿Un imperio se derrumba de golpe o poco a poco?", "scenario": "Nadie firmó un papel que dijera 'hoy termina el Imperio español'. Fue un proceso lento, como una grieta que se va abriendo en un muro hasta que este cede.", "body": "Esta semana investigarás las <b>causas económicas, políticas y sociales</b> que explican la decadencia del imperio, y aprenderás a conectarlas con sus consecuencias concretas."}, {"type": "theory", "kicker": "Historia · Conceptos clave", "h": "Tres tipos de causas, un mismo resultado", "body": "Los historiadores agrupan las causas de la decadencia en tres bloques. <b>Causas económicas</b>: la llegada masiva de plata de América provocó inflación y no se invirtió en desarrollar la industria propia; además, las guerras constantes vaciaban las arcas reales. <b>Causas políticas</b>: los validos gobernaban en lugar de los reyes, y conflictos como la pérdida de Portugal (1640) o la derrota en la Guerra de los Treinta Años (Paz de Westfalia, 1648) debilitaron el poder español en Europa. <b>Causas sociales</b>: una nobleza que no pagaba impuestos, un campesinado empobrecido y la expulsión de moriscos redujeron la mano de obra y el consumo interno.", "diagram": "<b>Causa económica</b> → plata devaluada, sin industria propia <br><b>Causa política</b> → validos débiles, pérdida de Portugal (1640) y Westfalia (1648) <br><b>Causa social</b> → nobleza sin impuestos, campesinado pobre <br><b>Efecto final</b> → un imperio enorme pero frágil por dentro"}, {"type": "quiz", "kicker": "Historia · Ponte a prueba", "h": "Relaciona causa y efecto", "q": "¿Cuál de las siguientes es una consecuencia directa de que la plata americana no se invirtiera en crear industria propia?", "opts": [{"t": "España dependía de productos extranjeros y sufría inflación", "ok": true}, {"t": "España se convirtió en la mayor potencia industrial de Europa", "ok": false}, {"t": "Portugal se unió definitivamente a la corona española", "ok": false}, {"t": "Carlos II tuvo muchos hijos que aseguraron su sucesión", "ok": false}], "okMsg": "Correcto. Sin industria propia, España compraba fuera lo que no producía, y los precios subían sin control.", "noMsg": "No exactamente. La consecuencia fue que España, al no invertir en su propia industria, dependía del extranjero y sufría inflación."}, {"type": "reflect", "kicker": "Historia · Tu turno", "h": "Analiza causa y efecto", "body": "Vas a elegir tres causas de la decadencia (una económica, una política y una social) y explicar la consecuencia concreta de cada una.", "prompt": "Elige una causa económica, una política y una social de la decadencia del Imperio español. Para cada una, escribe: 1) en qué consistió, y 2) qué consecuencia concreta tuvo (por ejemplo, la pérdida de Portugal en 1640 o el reconocimiento de la independencia de los Países Bajos en la Paz de Westfalia de 1648)."}]},
  "p6:Oct:3": {"title": "Huellas del Imperio en mi ciudad", "steps": [{"type": "hook", "kicker": "Historia · Semana 3", "h": "¿Y si el Imperio español sigue presente, sin que te dieras cuenta?", "scenario": "Pasas cada día por calles, plazas o edificios sin fijarte en sus nombres. Pero muchos de ellos guardan memoria de aquel imperio que se extendía por medio mundo.", "body": "Esta semana te toca convertirte en <b>investigador local</b>: buscar en tu propia ciudad o pueblo algún recuerdo, monumento, calle o edificio relacionado con el Imperio español de los siglos XVI y XVII."}, {"type": "theory", "kicker": "Historia · Conceptos clave", "h": "1640 y 1648: dos golpes al imperio", "body": "En <b>1640</b>, Portugal, que llevaba sesenta años unido a la corona española, se rebeló y consiguió su independencia definitiva: fue una señal clara de que el imperio ya no podía sostener tantos territorios a la vez. Ocho años después, en <b>1648</b>, la Paz de Westfalia puso fin a la Guerra de los Treinta Años y obligó a España a reconocer la independencia de las Provincias Unidas (los actuales Países Bajos). Estos dos hechos, separados por solo ocho años, muestran cómo el imperio iba perdiendo territorios y prestigio en toda Europa.", "diagram": "<b>1640</b> Portugal se independiza <br><b>1648</b> Paz de Westfalia: se pierden los Países Bajos <br>Ambos hechos = el imperio ya no controla lo que antes dominaba"}, {"type": "quiz", "kicker": "Historia · Ponte a prueba", "h": "Dos fechas, dos pérdidas", "q": "¿Qué ocurrió en la Paz de Westfalia de 1648?", "opts": [{"t": "España reconoció la independencia de las Provincias Unidas (Países Bajos)", "ok": true}, {"t": "España recuperó Portugal", "ok": false}, {"t": "Carlos II fue coronado rey", "ok": false}, {"t": "España conquistó nuevos territorios en América", "ok": false}], "okMsg": "Correcto. La Paz de Westfalia (1648) obligó a España a reconocer la independencia de los Países Bajos.", "noMsg": "No es correcto. En la Paz de Westfalia (1648), España tuvo que reconocer la independencia de las Provincias Unidas (Países Bajos)."}, {"type": "reflect", "kicker": "Historia · Tu turno", "h": "Sal a investigar tu ciudad", "body": "Vas a buscar, en tu ciudad o pueblo, algún resto visible del Imperio español de los siglos XVI-XVII: una calle, un monumento, un edificio o incluso el nombre de una plaza.", "prompt": "Busca en tu ciudad o pueblo un monumento, calle o edificio relacionado con el Imperio español de los siglos XVI o XVII. Describe qué es, dónde está y qué relación tiene con esa época (puedes preguntar a un adulto o buscar información si no lo sabes con seguridad). Si no encuentras nada en tu localidad, investiga uno de una ciudad cercana."}]},
  "p6:Oct:4": {"title": "Todo era vanidad: la lección del Eclesiastés", "steps": [{"type": "hook", "kicker": "Historia y Fe · Semana 4", "h": "¿De qué sirve construir un imperio que nunca se pone el sol, si al final se derrumba?", "scenario": "Un imperio con territorios en cuatro continentes terminó reducido, en apenas un siglo, a un reino debilitado y endeudado. Hace más de dos mil años, un rey sabio ya había reflexionado sobre esto.", "body": "El rey Salomón, en el libro de <b>Eclesiastés</b>, miró todo lo que había construido con sus propias manos y llegó a una conclusión sorprendente: \"todo era vanidad\". Esta semana vas a cerrar el tema de la decadencia del Imperio español conectándolo con esa reflexión bíblica."}, {"type": "theory", "kicker": "Historia y Fe · Conceptos clave", "h": "Lo que dice Eclesiastés 2:11", "body": "El versículo dice: \"<b>Miré yo todas las obras que habían hecho mis manos: todo era vanidad</b>\" (Eclesiastés 2:11). Salomón, uno de los reyes más ricos y poderosos de la historia, construyó palacios, jardines y ciudades, y aun así reconoció que todo aquello, sin Dios en el centro, no tenía sentido duradero. El Imperio español fue una obra humana gigantesca: ejércitos, riquezas, territorios inmensos... y, sin embargo, en menos de un siglo se debilitó hasta casi desaparecer. La Biblia nos enseña que ningún imperio humano es eterno, y que poner nuestra confianza solo en el poder o la riqueza es, tarde o temprano, \"vanidad\": algo que se desvanece.", "diagram": "Imperio español → poder, riqueza, territorios <br>Eclesiastés 2:11 → \"todo era vanidad\" <br>Lección → lo humano se desvanece; solo lo eterno permanece"}, {"type": "quiz", "kicker": "Historia y Fe · Ponte a prueba", "h": "¿Qué significa 'vanidad' en Eclesiastés?", "q": "Según Eclesiastés 2:11, ¿qué quiere decir Salomón cuando afirma que 'todo era vanidad'?", "opts": [{"t": "Que las grandes obras humanas, por sí solas, no dan un sentido duradero a la vida", "ok": true}, {"t": "Que construir un imperio es siempre un pecado", "ok": false}, {"t": "Que Salomón se arrepintió de ser rey", "ok": false}, {"t": "Que solo los imperios pequeños tienen sentido", "ok": false}], "okMsg": "Así es. Salomón, con todo su poder y riqueza, entendió que las obras humanas sin Dios no dan un sentido duradero.", "noMsg": "No es eso exactamente. Salomón quiere decir que las grandes obras humanas, por sí solas, no dan un sentido duradero a la vida."}, {"type": "reflect", "kicker": "Historia y Fe · Tu turno (entregable)", "h": "¿Qué aprendemos de la caída de los imperios?", "body": "Esta semana entregas el trabajo final del mes, conectando la historia del declive del Imperio español con la reflexión bíblica sobre la vanidad de las obras humanas.", "prompt": "Elabora tu trabajo 'La decadencia del Imperio Español': explica en tus palabras 1) tres causas de la caída del imperio (económicas, políticas y sociales), 2) qué relación encuentras entre esa historia y el versículo de Eclesiastés 2:11, y 3) qué aprendemos hoy, como personas, de la caída de los grandes imperios."}]},
  "p6:Nov:1": {"title": "Cervantes y el hidalgo que soñaba con ser caballero", "steps": [{"type": "hook", "kicker": "Lengua · Semana 1", "h": "¿Qué pasaría si te creyeras el protagonista de tus libros favoritos?", "scenario": "Imagina a un hombre de mediana edad, de pueblo, que lee tantas novelas de caballerías que termina convencido de ser un caballero andante. Monta en un caballo flaco, se pone una armadura oxidada y sale a buscar aventuras.", "body": "Así comienza <b>El ingenioso hidalgo don Quijote de la Mancha</b>, escrito por <b>Miguel de Cervantes</b> en el Siglo de Oro español. Esta semana empiezas tu primera lectura crítica de esta obra fundamental de la literatura en castellano."}, {"type": "theory", "kicker": "Lengua · Conceptos clave", "h": "Cervantes y su época", "body": "<b>Miguel de Cervantes</b> (1547-1616) vivió una vida de aventuras: fue soldado, quedó herido en la batalla de Lepanto, estuvo cautivo en Argel durante cinco años y pasó dificultades económicas casi toda su vida. Publicó la primera parte de <b>El Quijote</b> en 1605 y la segunda en 1615, durante el <b>Siglo de Oro</b>, la época de mayor esplendor de la literatura y el arte españoles. El argumento sigue a <b>Alonso Quijano</b>, un hidalgo que, tras leer demasiadas novelas de caballerías, decide convertirse en el caballero \"Don Quijote de la Mancha\" y recorrer España deshaciendo agravios e imponiendo justicia, aunque su visión de la realidad está deformada por sus lecturas.", "diagram": "<b>Cervantes</b> (1547-1616) → soldado, cautivo, escritor <br><b>1605</b> Primera parte de El Quijote <br><b>1615</b> Segunda parte <br><b>Argumento</b>: un hidalgo cree ser caballero andante y sale de aventuras"}, {"type": "quiz", "kicker": "Lengua · Ponte a prueba", "h": "¿Quién escribió El Quijote y cuándo?", "q": "¿En qué año se publicó la primera parte de El Quijote?", "opts": [{"t": "1605", "ok": true}, {"t": "1492", "ok": false}, {"t": "1648", "ok": false}, {"t": "1700", "ok": false}], "okMsg": "Correcto. Cervantes publicó la primera parte de El Quijote en 1605.", "noMsg": "No es correcto. La primera parte de El Quijote se publicó en 1605."}, {"type": "reflect", "kicker": "Lengua · Tu turno", "h": "Lee y resume", "body": "Vas a leer los dos primeros capítulos de tu edición de El Quijote adaptada para 6º de Primaria y a resumir lo que ocurre.", "prompt": "Lee los dos primeros capítulos de tu edición de El Quijote para 6º de Primaria. Después, resume el episodio en exactamente 8 oraciones, explicando quién es Alonso Quijano, por qué decide convertirse en caballero andante y qué le ocurre en su primera salida."}]},
  "p6:Nov:2": {"title": "Idealismo contra realismo: Quijote y Sancho", "steps": [{"type": "hook", "kicker": "Lengua · Semana 2", "h": "¿Prefieres soñar con lo imposible o ver el mundo tal como es?", "scenario": "Un caballero que ve gigantes donde solo hay molinos de viento cabalga junto a un campesino que ve, sencillamente, molinos de viento. Los dos miran lo mismo... y ven cosas completamente distintas.", "body": "Esta semana vas a analizar a los dos grandes personajes de la novela: <b>Don Quijote</b> y su escudero <b>Sancho Panza</b>, y lo que cada uno representa."}, {"type": "theory", "kicker": "Lengua · Conceptos clave", "h": "Dos formas de ver el mundo", "body": "<b>Don Quijote</b> representa el <b>idealismo</b>: cree en los valores de las novelas de caballerías (honor, justicia, amor eterno) y actúa según ese ideal, aunque choque una y otra vez con la realidad. <b>Sancho Panza</b>, su escudero, representa el <b>realismo</b> y el sentido común popular: es práctico, piensa en comer, dormir y ganar una \"ínsula\" para gobernar, y suele ver las cosas tal como son (unos molinos, una venta, un rebaño de ovejas). A través de esta pareja de personajes, Cervantes construye también una <b>crítica social</b>: se ríe de las novelas de caballerías pasadas de moda, pero también retrata con cariño y humor a la sociedad española de su tiempo, desde hidalgos empobrecidos hasta campesinos.", "diagram": "<b>Don Quijote</b> → idealismo, honor, justicia, imaginación <br><b>Sancho Panza</b> → realismo, sentido común, practicidad <br>Juntos → crítica social y humor del Siglo de Oro"}, {"type": "quiz", "kicker": "Lengua · Ponte a prueba", "h": "¿Quién representa qué?", "q": "¿Qué personaje representa el realismo y el sentido común popular en la novela?", "opts": [{"t": "Sancho Panza", "ok": true}, {"t": "Don Quijote", "ok": false}, {"t": "Dulcinea", "ok": false}, {"t": "El cura del pueblo", "ok": false}], "okMsg": "Correcto. Sancho Panza representa el realismo y el sentido común frente al idealismo de Don Quijote.", "noMsg": "No es correcto. Sancho Panza es quien representa el realismo y el sentido común popular."}, {"type": "reflect", "kicker": "Lengua · Tu turno", "h": "Compara a los dos personajes", "body": "Vas a analizar qué representa cada uno de los dos protagonistas y cómo se complementan a pesar de ser tan distintos.", "prompt": "Escribe un texto breve explicando: 1) qué representa Don Quijote (idealismo) y da un ejemplo del libro; 2) qué representa Sancho Panza (realismo) y da un ejemplo del libro; 3) por qué crees que Cervantes decidió poner juntos a dos personajes tan diferentes."}]},
  "p6:Nov:3": {"title": "La risa que esconde una crítica", "steps": [{"type": "hook", "kicker": "Lengua · Semana 3", "h": "¿Puede un libro hacerte reír y hacerte pensar al mismo tiempo?", "scenario": "Un hidalgo ataca unos molinos de viento convencido de que son gigantes malvados, y termina por los suelos, malherido y con la lanza rota. La escena es cómica... pero, si te fijas bien, también dice algo serio sobre la imaginación y la realidad.", "body": "Esta semana vas a identificar el <b>humor y la ironía</b> como herramientas literarias que Cervantes utiliza a lo largo de toda la novela."}, {"type": "theory", "kicker": "Lengua · Conceptos clave", "h": "El humor y la ironía en el Siglo de Oro", "body": "En el <b>Siglo de Oro</b>, muchos autores usaban el humor no solo para entretener, sino para hacer <b>crítica social</b> de forma indirecta, evitando la censura. Cervantes utiliza la <b>ironía</b> (decir algo dando a entender lo contrario, o mostrar el contraste entre lo que un personaje cree y lo que realmente ocurre) para reírse con cariño de las novelas de caballerías y de ciertos vicios de la sociedad de su tiempo. El lenguaje también contribuye al humor: Don Quijote habla con un estilo <b>arcaico y solemne</b>, propio de los libros de caballerías, mientras que Sancho usa un lenguaje <b>popular</b>, lleno de refranes; ese choque de registros, entre lo elevado y lo cotidiano, es una de las grandes fuentes de comicidad de la obra.", "diagram": "<b>Ironía</b> → contraste entre lo que Quijote cree y lo que realmente pasa <br><b>Lenguaje de Quijote</b> → solemne, arcaico, de caballerías <br><b>Lenguaje de Sancho</b> → popular, refranes <br>Choque de estilos → humor + crítica social"}, {"type": "quiz", "kicker": "Lengua · Ponte a prueba", "h": "¿Cómo crea Cervantes el humor?", "q": "¿Cuál de estos recursos usa Cervantes para crear humor e ironía en El Quijote?", "opts": [{"t": "El contraste entre el lenguaje solemne de Quijote y el habla popular de Sancho", "ok": true}, {"t": "Escribir toda la novela en verso", "ok": false}, {"t": "Evitar cualquier tipo de crítica social", "ok": false}, {"t": "Usar únicamente palabras inventadas sin sentido", "ok": false}], "okMsg": "Exacto. El contraste entre el habla elevada de Quijote y la popular de Sancho es una fuente clave de humor.", "noMsg": "No es correcto. Cervantes crea humor, entre otras cosas, contrastando el lenguaje solemne de Quijote con el habla popular de Sancho."}, {"type": "reflect", "kicker": "Lengua · Tu turno", "h": "Encuentra el humor en el texto", "body": "Vas a buscar en los capítulos leídos un momento concreto de humor y a explicar cómo lo construye Cervantes con el lenguaje.", "prompt": "Identifica un momento de humor en los capítulos que has leído de El Quijote. Descríbelo brevemente y explica qué recurso usa Cervantes para producir ese humor (por ejemplo: un contraste entre lo que el personaje imagina y lo que realmente ocurre, el lenguaje solemne de Quijote, un refrán de Sancho...)."}]},
  "p6:Nov:4": {"title": "¿Loco o sabio? La sabiduría que viene de Dios", "steps": [{"type": "hook", "kicker": "Lengua y Fe · Semana 4", "h": "¿Es de verdad un loco quien defiende ideales en un mundo que ya no cree en ellos?", "scenario": "Todos en la novela consideran loco a Don Quijote. Y sin embargo, muchos de sus discursos sobre la justicia, la libertad o la dignidad humana están llenos de una sabiduría que sorprende incluso hoy.", "body": "Esta semana vas a cerrar tu análisis literario de El Quijote reflexionando sobre esa pregunta y conectándola con lo que dice la Biblia sobre el origen verdadero de la sabiduría."}, {"type": "theory", "kicker": "Lengua y Fe · Conceptos clave", "h": "Lo que dice Proverbios 2:6", "body": "El versículo de esta semana dice: \"<b>Porque el Señor da la sabiduría, y de su boca viene el conocimiento</b>\" (Proverbios 2:6). En la novela, Don Quijote parece loco por confundir la realidad con sus lecturas, pero en muchos momentos pronuncia discursos profundamente sabios sobre la justicia, la libertad o el valor de las personas. Cervantes juega precisamente con esa paradoja: locura y sabiduría conviviendo en un mismo personaje. La Biblia nos enseña algo parecido desde otro ángulo: la verdadera sabiduría no nace solo de la inteligencia o de la experiencia humana, sino que <b>viene de Dios</b>. Por eso, antes de juzgar a alguien por ser distinto o \"idealista\", vale la pena preguntarse si detrás de esa diferencia hay, en realidad, una forma de sabiduría.", "diagram": "Don Quijote → parece loco, pero a veces habla con sabiduría <br>Proverbios 2:6 → \"el Señor da la sabiduría\" <br>Pregunta final → ¿locura o sabiduría? ¿de dónde viene la sabiduría verdadera?"}, {"type": "quiz", "kicker": "Lengua y Fe · Ponte a prueba", "h": "¿De dónde viene la sabiduría según Proverbios 2:6?", "q": "Según Proverbios 2:6, ¿de dónde viene la verdadera sabiduría?", "opts": [{"t": "Del Señor (Dios)", "ok": true}, {"t": "Únicamente de leer muchos libros, como le pasó a Don Quijote", "ok": false}, {"t": "De la experiencia de los caballeros andantes", "ok": false}, {"t": "De ser rico y poderoso", "ok": false}], "okMsg": "Correcto. Proverbios 2:6 dice que es el Señor quien da la sabiduría y el conocimiento.", "noMsg": "No es correcto. Según Proverbios 2:6, es el Señor quien da la sabiduría y de su boca viene el conocimiento."}, {"type": "reflect", "kicker": "Lengua y Fe · Tu turno (entregable)", "h": "¿Es el Quijote un loco o un sabio?", "body": "Esta semana entregas tu análisis literario final sobre El Quijote, uniendo lo que has aprendido sobre el personaje con la reflexión bíblica sobre la sabiduría.", "prompt": "Elabora tu análisis literario '¿Es el Quijote un loco o un sabio?': explica 1) al menos dos ejemplos de la novela donde Don Quijote parece loco y dos donde parece sabio; 2) tu propia opinión razonada sobre si es más loco o más sabio; y 3) qué relación encuentras entre esta pregunta y el versículo de Proverbios 2:6 sobre el origen de la verdadera sabiduría."}]},
  "p6:Dic:1": {"title": "El villancico: poesía popular que canta un misterio", "steps": [{"type": "hook", "kicker": "Historia Cultural · Diciembre · Semana 1", "h": "¿Sabías que un villancico no siempre fue una canción de Navidad?", "scenario": "Imagina una aldea castellana en el siglo XV: en la plaza, el pueblo canta coplas sencillas, con estribillo repetido, para celebrar la fiesta del lugar, no siempre religiosa.", "body": "La palabra <b>villancico</b> viene de <b>villano</b>, el habitante del pueblo o villa. Con el tiempo, esta forma poética popular se llenó de contenido religioso y se convirtió en el vehículo perfecto para explicar, con palabras sencillas, el misterio más grande de la fe cristiana: que Dios se hizo niño."}, {"type": "theory", "kicker": "Historia Cultural · Diciembre · Semana 1", "h": "Estructura y mensaje del villancico", "body": "El villancico clásico se construye con un <b>estribillo</b> (verso o versos que se repiten) y <b>coplas</b> o <b>estrofas</b> que desarrollan el tema. Nació en la Edad Media como canción popular, muchas veces profana, pero alcanzó su esplendor teológico en el <b>Siglo de Oro</b> (siglos XVI-XVII), cuando poetas de la época lo usaron para hablar del nacimiento de Cristo con lenguaje sencillo pero profundo. Su función no es solo estética: busca transmitir un <b>mensaje teológico</b> —la humildad de Dios, la alegría de la salvación— de forma memorable, cantable y accesible a todo el pueblo, culto o no.", "diagram": "<b>VILLANCICO</b><br>Origen: villa (pueblo) → canción popular<br>Edad Media: tema variado, no solo religioso<br>Siglo de Oro: forma + <b>teología</b> del nacimiento<br>Estructura: <b>Estribillo</b> ↔ <b>Coplas</b>"}, {"type": "quiz", "kicker": "Historia Cultural · Diciembre · Semana 1", "h": "Comprueba lo que has aprendido", "q": "¿Por qué se dice que el villancico es una forma 'popular' de transmitir teología?", "opts": [{"t": "Porque usa una estructura sencilla y repetitiva (estribillo/coplas) para que todo el pueblo pueda cantarlo y entender su mensaje", "ok": true}, {"t": "Porque solo lo cantaban los reyes en la corte", "ok": false}, {"t": "Porque estaba escrito en latín para los sacerdotes", "ok": false}, {"t": "Porque no tenía ningún contenido religioso", "ok": false}], "okMsg": "Exacto: el villancico convierte un misterio profundo en algo cantable por cualquiera.", "noMsg": "Repasa la teoría: el villancico usa estribillo y coplas precisamente para llegar a todo el pueblo, no solo a una élite."}, {"type": "reflect", "kicker": "Historia Cultural · Diciembre · Semana 1", "h": "Analiza un villancico clásico", "body": "Vas a leer un villancico clásico que tu profesor te facilite e identificar su estructura y su mensaje.", "prompt": "Elige un villancico clásico. Señala dónde está el <b>estribillo</b> y dónde las <b>coplas</b>. Después, escribe en 4-5 líneas qué <b>mensaje teológico</b> transmite sobre el nacimiento de Jesús: ¿qué dice sobre quién es Dios y cómo actúa?"}]},
  "p6:Dic:2": {"title": "Lucas, el narrador: técnicas literarias en el relato de la Natividad", "steps": [{"type": "hook", "kicker": "Historia Cultural · Diciembre · Semana 2", "h": "¿Puede un texto bíblico leerse como una obra literaria?", "scenario": "Un historiador y un novelista leen el mismo texto: Lucas 2. El historiador busca datos, el censo, el lugar. El novelista busca algo distinto: cómo está contada la historia.", "body": "El evangelista <b>Lucas</b> no solo relata hechos: los <b>narra</b> con recursos propios de la literatura —contraste, detalle significativo, punto de vista— para que el lector sienta el peso del acontecimiento: el Creador del universo nace en un pesebre."}, {"type": "theory", "kicker": "Historia Cultural · Diciembre · Semana 2", "h": "Técnicas narrativas de Lucas 2:1-20", "body": "Lucas sitúa la escena en un <b>contexto histórico preciso</b> (el censo de Augusto, Cirenio gobernador de Siria), lo que da <b>verosimilitud</b> al relato. Después usa el recurso del <b>contraste</b>: el emperador más poderoso del mundo ordena un censo, y en ese mismo momento nace, en la pobreza de un pesebre, un rey mayor que él. Lucas elige también un <b>punto de vista</b> inesperado: los primeros testigos no son sacerdotes ni nobles, sino <b>pastores</b>, gente humilde. Y usa el <b>diálogo</b> (el mensaje del ángel) y la <b>imagen sensorial</b> (el pesebre, los pañales, la gloria que resplandece) para que el lector no solo entienda, sino que <b>vea</b> la escena.", "diagram": "<b>LUCAS 2:1-20 — RECURSOS</b><br>Contexto histórico → verosimilitud<br>Contraste → emperador vs. niño en pesebre<br>Punto de vista → pastores (humildes)<br>Imágenes sensoriales → pesebre, gloria, pañales"}, {"type": "quiz", "kicker": "Historia Cultural · Diciembre · Semana 2", "h": "Comprueba lo que has aprendido", "q": "¿Qué recurso literario usa Lucas al situar el nacimiento de Jesús junto al censo del emperador Augusto?", "opts": [{"t": "El contraste, para resaltar que el rey verdadero nace en la pobreza mientras el poder mundial se ocupa de un censo", "ok": true}, {"t": "La rima, para que el texto se pueda cantar", "ok": false}, {"t": "La ironía cómica, para hacer reír al lector", "ok": false}, {"t": "La exageración numérica, para impresionar con cifras", "ok": false}], "okMsg": "Correcto: ese contraste entre el poder de Roma y la humildad del pesebre es clave en la narración de Lucas.", "noMsg": "Piensa de nuevo: Lucas coloca dos poderes uno junto al otro —el del emperador y el del niño— para que el contraste hable por sí mismo."}, {"type": "reflect", "kicker": "Historia Cultural · Diciembre · Semana 2", "h": "Analiza el texto como literatura", "body": "Vas a leer Lucas 2:1-20 completo y fijarte en cómo está contado, no solo en qué cuenta.", "prompt": "Lee Lucas 2:1-20. Elige <b>tres momentos</b> del texto y, para cada uno, escribe qué <b>técnica narrativa</b> usa Lucas (contraste, punto de vista, imagen sensorial, diálogo...) y qué efecto produce en el lector."}]},
  "p6:Dic:3": {"title": "Tu propio villancico: de lector a poeta", "steps": [{"type": "hook", "kicker": "Historia Cultural · Diciembre · Semana 3", "h": "Has leído villancicos y el relato de Lucas. ¿Y si ahora fueras tú quien escribe?", "scenario": "Durante siglos, poetas anónimos y conocidos han puesto en verso el mismo acontecimiento. Cada generación necesita sus propias palabras para seguir contando la misma historia.", "body": "Escribir un villancico no es solo rimar: es elegir <b>qué parte del misterio</b> quieres destacar —la humildad, la alegría, la esperanza— y encontrar <b>imágenes</b> propias para expresarlo, como hicieron los poetas del Siglo de Oro."}, {"type": "theory", "kicker": "Historia Cultural · Diciembre · Semana 3", "h": "Cómo construir tu villancico", "body": "Recuerda la estructura aprendida: un <b>estribillo</b> breve y memorable, y <b>coplas</b> que desarrollan la idea. Para 12 versos, puedes organizar, por ejemplo: 4 versos de estribillo + 8 versos en dos coplas de 4, o bien combinar estribillo y estrofas cortas. Antes de escribir, decide tu <b>mensaje teológico central</b> (inspirado en Lucas 2 o en Juan 1:14): ¿la humildad de Dios?, ¿la luz que llega a la oscuridad?, ¿la alegría de los pastores? Usa <b>imágenes concretas</b> (el pesebre, la noche, la estrella, el pañal) en vez de ideas abstractas, tal como hacía la poesía del Siglo de Oro.", "diagram": "<b>TU VILLANCICO (12 versos)</b><br>1. Elige el <b>mensaje</b> central<br>2. Escribe el <b>estribillo</b> (repetible)<br>3. Desarrolla en <b>coplas</b><br>4. Usa <b>imágenes concretas</b>, no solo ideas"}, {"type": "quiz", "kicker": "Historia Cultural · Diciembre · Semana 3", "h": "Comprueba lo que has aprendido", "q": "Antes de escribir un villancico, ¿qué debe decidir primero el poeta, según el modelo del Siglo de Oro?", "opts": [{"t": "El mensaje teológico central que quiere transmitir, y luego buscar imágenes concretas para expresarlo", "ok": true}, {"t": "El número exacto de sílabas de cada verso, sin pensar en el contenido", "ok": false}, {"t": "El nombre del villancico, que debe ser siempre en latín", "ok": false}, {"t": "La melodía musical antes que cualquier otra cosa", "ok": false}], "okMsg": "Así es: primero el mensaje, después la forma y las imágenes que lo hacen memorable.", "noMsg": "Repasa la teoría: lo primero es decidir qué idea teológica quieres transmitir; la forma viene después."}, {"type": "reflect", "kicker": "Historia Cultural · Diciembre · Semana 3", "h": "Escribe tu villancico", "body": "Es tu turno de convertirte en poeta, siguiendo el modelo de estribillo + coplas.", "prompt": "Escribe un villancico de <b>12 versos</b> (estribillo + coplas) sobre el <b>significado del nacimiento de Jesús</b>. Elige un mensaje central (humildad, luz, esperanza...) y usa al menos <b>dos imágenes concretas</b> tomadas de Lucas 2."}]},
  "p6:Dic:4": {"title": "El Verbo se hizo carne: el misterio detrás de todos los villancicos", "steps": [{"type": "hook", "kicker": "Historia Cultural · Diciembre · Semana 4", "h": "¿Qué frase resume, en solo seis palabras, todo lo que has estudiado este mes?", "scenario": "Villancicos, poesía del Siglo de Oro, el relato de Lucas... todos hablan, con distintas palabras, de lo mismo. El apóstol Juan lo condensó en una frase que ha marcado la literatura y la teología cristiana durante dos mil años.", "body": "<b>'Y el Verbo se hizo carne y habitó entre nosotros, lleno de gracia y de verdad'</b> (Juan 1:14). Esta frase es el resumen teológico de todo lo que los villancicos cantan y Lucas narra: Dios mismo entra en la historia humana."}, {"type": "theory", "kicker": "Historia Cultural · Diciembre · Semana 4", "h": "El Verbo hecho carne: síntesis del mes", "body": "Juan usa la palabra griega <b>'Logos'</b> (traducida como 'Verbo'), que significaba para los griegos la razón última del universo, y para los judíos, la palabra creadora de Dios (Génesis 1). Juan afirma algo asombroso: ese Verbo eterno <b>'se hizo carne'</b>, es decir, se volvió completamente humano, frágil, mortal. Esta es la <b>Encarnación</b>: el mismo misterio que el villancico canta con sencillez popular y que Lucas narra con detalle histórico y literario. La frase añade dos palabras clave: <b>'gracia'</b> (un don inmerecido) y <b>'verdad'</b> (la realidad última de Dios revelada). Literatura, historia y teología convergen en esta única idea.", "diagram": "<b>SÍNTESIS DE DICIEMBRE</b><br>Villancico → canta el misterio<br>Lucas 2 → narra el misterio con recursos literarios<br>Juan 1:14 → <b>nombra</b> el misterio: 'el Verbo se hizo carne'<br>Resultado: <b>Encarnación</b> = gracia + verdad"}, {"type": "quiz", "kicker": "Historia Cultural · Diciembre · Semana 4", "h": "Comprueba lo que has aprendido", "q": "Según Juan 1:14, ¿qué significa que 'el Verbo se hizo carne'?", "opts": [{"t": "Que el Verbo eterno de Dios se volvió completamente humano, entrando en la historia con gracia y verdad", "ok": true}, {"t": "Que un poeta escribió un poema sobre la carne y los alimentos de Navidad", "ok": false}, {"t": "Que la palabra 'Verbo' es solo un término gramatical sin relación con la Navidad", "ok": false}, {"t": "Que los pastores escribieron el evangelio de Juan", "ok": false}], "okMsg": "Correcto: la Encarnación es que Dios mismo se hace humano, uniendo lo divino y lo humano.", "noMsg": "Vuelve a leer la teoría: 'el Verbo se hizo carne' significa que Dios mismo se volvió humano."}, {"type": "reflect", "kicker": "Historia Cultural · Diciembre · Semana 4", "h": "Conecta todo lo aprendido en tu portfolio", "body": "Vas a cerrar el mes reuniendo tu villancico, tu análisis de Lucas 2 y esta reflexión final en un portfolio literario.", "prompt": "Escribe un texto breve (8-10 líneas) titulado <b>'El misterio de la Encarnación'</b> en el que expliques, con tus propias palabras y citando Juan 1:14, cómo se conecta este versículo con el villancico que escribiste y con el relato de Lucas 2. Incluye este texto en tu <b>portfolio literario 'Navidad en la literatura'</b>."}]},
  "p6:Feb:1": {"title": "Feijoo: el fraile que quiso pensar con la razón", "steps": [{"type": "hook", "kicker": "Historia · Febrero · Semana 1", "h": "¿Puede un fraile benedictino ser también un pensador revolucionario?", "scenario": "España, primera mitad del siglo XVIII. Mientras muchos siguen aceptando creencias populares sin cuestionarlas, un monje llamado Benito Jerónimo Feijoo empieza a escribir ensayos que piden algo nuevo: comprobar las cosas antes de creerlas.", "body": "<b>Feijoo</b> es una de las figuras centrales de la <b>Ilustración española</b>. Sin dejar de ser un religioso convencido, defendió el uso de la <b>razón crítica</b> para combatir supersticiones, errores y falsas creencias extendidas en su época."}, {"type": "theory", "kicker": "Historia · Febrero · Semana 1", "h": "El método y el argumento de Feijoo", "body": "Feijoo escribió obras como el <b>'Teatro Crítico Universal'</b>, donde analizaba creencias populares, supuestos milagros falsos o teorías erróneas, aplicando <b>observación</b> y <b>argumentación razonada</b>. Su objetivo principal era combatir la <b>credulidad</b> —creer cualquier cosa sin comprobarla— no la fe cristiana en sí. Para Feijoo, la verdadera fe no tiene nada que temer de la razón bien empleada: al contrario, se fortalece cuando se separa de la superstición y el engaño. Este es el <b>argumento central</b> que debes identificar en cualquier texto suyo: usar la razón y la evidencia para depurar el conocimiento, sin por ello abandonar la fe.", "diagram": "<b>FEIJOO — ARGUMENTO PRINCIPAL</b><br>Problema: supersticiones y creencias sin comprobar<br>Método: <b>observación</b> + <b>razón crítica</b><br>Objetivo: combatir el error, no la fe<br>Obra clave: <b>Teatro Crítico Universal</b>"}, {"type": "quiz", "kicker": "Historia · Febrero · Semana 1", "h": "Comprueba lo que has aprendido", "q": "¿Cuál era el objetivo principal de Feijoo al usar la razón crítica en sus escritos?", "opts": [{"t": "Combatir la superstición y las creencias falsas, no destruir la fe cristiana", "ok": true}, {"t": "Demostrar que la religión católica era falsa por completo", "ok": false}, {"t": "Defender todas las creencias populares sin excepción", "ok": false}, {"t": "Escribir solo sobre temas militares y de guerra", "ok": false}], "okMsg": "Correcto: Feijoo quería depurar el conocimiento de errores, no eliminar la fe.", "noMsg": "Repasa la teoría: Feijoo usaba la razón contra la superstición, pero seguía siendo un religioso convencido."}, {"type": "reflect", "kicker": "Historia · Febrero · Semana 1", "h": "Analiza un texto de Feijoo", "body": "Vas a leer un fragmento adaptado de un texto de Feijoo que tu profesor te entregará.", "prompt": "Lee el fragmento de Feijoo. Escribe en 4-5 líneas cuál es su <b>argumento principal</b>: ¿qué creencia o error critica?, ¿qué método usa para rebatirlo (observación, comparación, lógica)?, ¿a qué conclusión llega?"}]},
  "p6:Feb:2": {"title": "1716: el mapa de España cambia para siempre", "steps": [{"type": "hook", "kicker": "Historia · Febrero · Semana 2", "h": "¿Qué pasa cuando un rey decide que todo el país debe gobernarse con las mismas leyes?", "scenario": "Tras años de Guerra de Sucesión, el nuevo rey Felipe V, de la casa de Borbón, se enfrenta a territorios que habían apoyado a su rival. Su respuesta cambiará el mapa político de España.", "body": "Los <b>Decretos de Nueva Planta</b>, firmados por <b>Felipe V</b> entre 1707 y 1716, suprimieron los fueros e instituciones propias de varios territorios de la <b>Corona de Aragón</b>, imponiendo las leyes de Castilla en su lugar."}, {"type": "theory", "kicker": "Historia · Febrero · Semana 2", "h": "Qué regiones perdieron autonomía y por qué", "body": "Los Decretos de Nueva Planta afectaron a los antiguos reinos de la <b>Corona de Aragón</b>: <b>Aragón</b> y <b>Valencia</b> (1707), <b>Mallorca</b> (1715) y <b>Cataluña</b> (1716), el último en caer tras el sitio de Barcelona. Estos territorios perdieron sus <b>fueros</b> (leyes propias), sus <b>Cortes</b> particulares y buena parte de su autogobierno, al haber apoyado al archiduque Carlos en la Guerra de Sucesión en lugar de a Felipe V. En cambio, <b>Navarra</b> y las <b>provincias vascas</b>, que habían apoyado a Felipe V, conservaron sus fueros. El resultado fue un estado más <b>centralizado</b>, con Castilla como modelo administrativo único: un paso importante hacia la España moderna, aunque a costa de la diversidad política anterior.", "diagram": "<b>NUEVA PLANTA (1707-1716)</b><br>Perdieron fueros: Aragón, Valencia, Mallorca, Cataluña<br>Conservaron fueros: Navarra, provincias vascas<br>Causa: apoyo al bando perdedor en la Guerra de Sucesión<br>Efecto: España más <b>centralizada</b>"}, {"type": "quiz", "kicker": "Historia · Febrero · Semana 2", "h": "Comprueba lo que has aprendido", "q": "¿Qué territorios perdieron su autonomía y fueros propios con los Decretos de Nueva Planta?", "opts": [{"t": "Los antiguos reinos de la Corona de Aragón: Aragón, Valencia, Mallorca y Cataluña", "ok": true}, {"t": "Navarra y las provincias vascas", "ok": false}, {"t": "Solo Andalucía y Extremadura", "ok": false}, {"t": "Ningún territorio perdió autonomía, solo Castilla la ganó", "ok": false}], "okMsg": "Correcto: fueron los territorios de la antigua Corona de Aragón, por haber apoyado al otro bando en la guerra.", "noMsg": "Repasa la teoría: los decretos afectaron a Aragón, Valencia, Mallorca y Cataluña, no a Navarra ni al País Vasco."}, {"type": "reflect", "kicker": "Historia · Febrero · Semana 2", "h": "Trabaja con el mapa de España de 1716", "body": "Vas a analizar un mapa de España tras la Nueva Planta y marcar los cambios de autonomía territorial.", "prompt": "Sobre un mapa de España, señala con un color los territorios que <b>perdieron</b> sus fueros con la Nueva Planta y con otro color los que los <b>conservaron</b>. Después, escribe 3-4 líneas explicando por qué crees que Felipe V trató de forma distinta a unos territorios y a otros."}]},
  "p6:Feb:3": {"title": "¿Razón o fe? El debate del siglo de las luces", "steps": [{"type": "hook", "kicker": "Historia · Febrero · Semana 3", "h": "¿Tienen que elegir las personas entre pensar con la cabeza o creer con el corazón?", "scenario": "En el siglo XVIII, llamado 'el Siglo de las Luces', muchos pensadores europeos empiezan a preguntarse si la razón humana puede sustituir a la fe religiosa como guía de la vida. En España, el debate tiene matices propios.", "body": "Frente a quienes veían la <b>razón</b> y la <b>fe</b> como enemigas irreconciliables, ilustrados españoles como <b>Gaspar Melchor de Jovellanos</b> defendieron que ambas podían y debían convivir, cada una en su terreno."}, {"type": "theory", "kicker": "Historia · Febrero · Semana 3", "h": "Jovellanos y la convivencia entre fe y razón", "body": "<b>Jovellanos</b> fue un jurista, escritor y reformista ilustrado que impulsó mejoras educativas, económicas y sociales en España aplicando la razón crítica —igual que Feijoo—, pero sin renunciar a su fe cristiana. Para muchos ilustrados españoles, la razón servía para mejorar la sociedad, la agricultura, la educación o la justicia, mientras que la fe respondía a preguntas distintas: el sentido último de la vida, la relación con Dios, la moral. Esta postura, llamada a veces <b>'Ilustración católica'</b>, se distingue de la Ilustración más radical de otros países europeos, que sí llegó a plantear la razón como sustituto de la religión. El debate honesto reconoce ambas posturas: hay quien defiende que fe y razón son <b>complementarias</b> (cada una responde a preguntas distintas) y quien defiende que son <b>incompatibles</b> (solo una puede ser guía verdadera). No existe una única respuesta aceptada por todos; es un debate que sigue abierto hoy.", "diagram": "<b>DEBATE FE Y RAZÓN (S. XVIII)</b><br>Postura A: son <b>complementarias</b> (Jovellanos, Feijoo)<br>Postura B: son <b>incompatibles</b> (Ilustración radical europea)<br>Jovellanos: razón para reformar la sociedad + fe para el sentido último"}, {"type": "quiz", "kicker": "Historia · Febrero · Semana 3", "h": "Comprueba lo que has aprendido", "q": "¿Qué postura defendía Jovellanos sobre la relación entre razón y fe?", "opts": [{"t": "Que podían convivir, cada una respondiendo a preguntas distintas de la vida humana", "ok": true}, {"t": "Que la razón debía eliminar por completo cualquier creencia religiosa", "ok": false}, {"t": "Que la fe debía prohibir el uso de la razón en cualquier ámbito", "ok": false}, {"t": "Que este tema no interesaba a los ilustrados españoles", "ok": false}], "okMsg": "Correcto: Jovellanos representa la llamada 'Ilustración católica', que buscaba la convivencia entre ambas.", "noMsg": "Repasa la teoría: Jovellanos defendía que razón y fe podían convivir, cada una en su propio terreno."}, {"type": "reflect", "kicker": "Historia · Febrero · Semana 3", "h": "Participa en el debate", "body": "Vas a preparar y participar en un debate en clase sobre si la razón y la fe pueden caminar juntas.", "prompt": "Prepara <b>dos argumentos</b>: uno a favor de que fe y razón son complementarias (apóyate en el ejemplo de Jovellanos) y uno que exponga la postura contraria (que son incompatibles). Después, escribe tu <b>propia opinión razonada</b> en 5-6 líneas, explicando por qué la sostienes."}]},
  "p6:Feb:4": {"title": "En Cristo, todos los tesoros de la sabiduría", "steps": [{"type": "hook", "kicker": "Historia · Febrero · Semana 4", "h": "Después de todo este debate sobre razón y fe, ¿qué dice la Biblia misma sobre el conocimiento?", "scenario": "Mientras Feijoo defendía la razón crítica y Jovellanos buscaba la convivencia entre fe y ciencia, un texto escrito muchos siglos antes ya ofrecía una perspectiva sorprendente sobre dónde se encuentra la verdadera sabiduría.", "body": "<b>'En Cristo están escondidos todos los tesoros de la sabiduría y del conocimiento'</b> (Colosenses 2:3). Este versículo no rechaza la razón ni el conocimiento humano: los sitúa en su lugar, dentro de una visión más amplia."}, {"type": "theory", "kicker": "Historia · Febrero · Semana 4", "h": "Sabiduría, conocimiento y fe: la síntesis final", "body": "El apóstol Pablo, autor de la carta a los Colosenses, no está diciendo que estudiar historia, ciencia o filosofía sea inútil. Al contrario: afirma que toda <b>sabiduría</b> (saber vivir bien) y todo <b>conocimiento</b> (saber verdadero sobre el mundo) tienen su origen y su sentido último en Dios. Esto conecta directamente con el debate de esta unidad: Feijoo usaba la razón para buscar la verdad y combatir el error, y Jovellanos defendía que la razón y la fe podían convivir porque, en el fondo, ambas buscan lo mismo desde ángulos distintos. Colosenses 2:3 ofrece una tercera perspectiva: no coloca la razón contra la fe, sino que sitúa toda búsqueda honesta de conocimiento dentro del mismo horizonte de sentido que ofrece la fe. Es una manera de cerrar el debate del siglo XVIII con una pregunta abierta y honesta, no con una respuesta impuesta.", "diagram": "<b>SÍNTESIS DE FEBRERO</b><br>Nueva Planta → poder político centralizado<br>Feijoo → razón crítica contra el error<br>Jovellanos → razón y fe conviven<br>Col 2:3 → sabiduría y conocimiento <b>tienen sentido último en Cristo</b>"}, {"type": "quiz", "kicker": "Historia · Febrero · Semana 4", "h": "Comprueba lo que has aprendido", "q": "Según Colosenses 2:3, ¿qué relación existe entre la sabiduría, el conocimiento y Cristo?", "opts": [{"t": "Que todos los tesoros de la sabiduría y el conocimiento están escondidos en Cristo, es decir, encuentran en él su sentido último", "ok": true}, {"t": "Que el conocimiento humano y la ciencia son completamente inútiles", "ok": false}, {"t": "Que solo los teólogos pueden tener conocimiento verdadero", "ok": false}, {"t": "Que este versículo no tiene relación alguna con el debate entre fe y razón", "ok": false}], "okMsg": "Correcto: el versículo sitúa la sabiduría y el conocimiento humano dentro del sentido último que da la fe.", "noMsg": "Vuelve a leer la teoría: Colosenses 2:3 no rechaza el conocimiento humano, sino que lo sitúa en un horizonte más amplio."}, {"type": "reflect", "kicker": "Historia · Febrero · Semana 4", "h": "Cierra tu trabajo del mes", "body": "Vas a redactar el trabajo final de febrero conectando todo lo estudiado con el versículo bíblico.", "prompt": "Escribe tu trabajo <b>'La Ilustración española y la fe'</b> (8-10 líneas): explica cómo Feijoo y Jovellanos entendían la relación entre razón y fe, cuál es tu propia postura tras el debate, y cómo se relaciona todo esto con Colosenses 2:3."}]},
  "p6:Mar:1": {"title": "Detectives del Pasado: Leer para Descubrir", "steps": [{"type": "hook", "kicker": "Un mensaje desde 1812", "h": "¿Puede un texto de hace más de 200 años hablarte directamente a ti?", "scenario": "Imagina que abres un baúl antiguo en el desván de tus abuelos y encuentras un papel amarillento con letra apretada. Es el preámbulo de una Constitución escrita hace dos siglos.", "body": "Antes de opinar sobre un texto histórico hay que aprender a <b>leerlo bien</b>: quién lo escribió, cuándo, y sobre todo, <b>para qué</b>. Esta semana empiezas a entrenar tu mirada de historiador."}, {"type": "theory", "kicker": "Herramientas de lectura histórica", "h": "¿Qué debo buscar en un texto histórico?", "body": "Todo texto histórico tiene un <b>autor</b>, una <b>época</b> y una <b>intención</b>. La intención es la razón por la que se escribió: ¿informar, convencer, defender una idea, justificar una decisión? En el preámbulo de la Constitución de 1812, los diputados de Cádiz explican <b>por qué</b> era necesario un nuevo texto legal para la nación. Reconocer esa intención es el primer paso de cualquier buen comentario de texto.", "diagram": "TEXTO HISTÓRICO<br><b>¿Quién lo escribe?</b> → Autor y época<br><b>¿Para quién?</b> → Destinatario<br><b>¿Para qué?</b> → Intención del texto"}, {"type": "quiz", "kicker": "Ponte a prueba", "h": "Intención de un texto histórico", "q": "Cuando los diputados de Cádiz escriben el preámbulo de la Constitución de 1812, ¿cuál es su intención principal?", "opts": [{"t": "Contar una historia inventada para entretener", "ok": false}, {"t": "Explicar y justificar la necesidad de una nueva ley fundamental para la nación", "ok": true}, {"t": "Describir el paisaje de la ciudad de Cádiz", "ok": false}, {"t": "Anunciar una fiesta popular", "ok": false}], "okMsg": "Exacto. Los textos históricos casi siempre buscan explicar, justificar o defender una idea ante quien los lee.", "noMsg": "Piénsalo de nuevo: un preámbulo constitucional no cuenta una historia ni describe paisajes, sino que <b>justifica</b> una decisión importante."}, {"type": "reflect", "kicker": "Tu turno de investigar", "h": "Lee como un historiador", "body": "Consigue o pide el texto del preámbulo de la Constitución de 1812 (tu profe puede dártelo). Léelo despacio, subrayando las palabras que no entiendas.", "prompt": "Escribe en tu cuaderno: 1) Quién escribe el texto y en qué año. 2) Dos frases que muestren su intención. 3) En una sola frase, explica con tus palabras <b>para qué</b> se escribió este texto."}]},
  "p6:Mar:2": {"title": "Mi Primer Comentario de Texto", "steps": [{"type": "hook", "kicker": "El reto del comentarista", "h": "¿Y si tu opinión sobre un texto tuviera que convencer a un tribunal?", "scenario": "Un comentario de texto no es un resumen: es como defender ante un jurado lo que el texto dice, cómo lo dice y qué opinas tú sobre ello.", "body": "Esta semana aprenderás la <b>estructura</b> del comentario de texto histórico: introducción, análisis y reflexión. Con ella construirás argumentos sólidos, no simples impresiones."}, {"type": "theory", "kicker": "La estructura del comentario", "h": "¿Cómo se organiza un buen comentario de texto?", "body": "Un comentario de texto histórico se divide en tres partes: la <b>introducción</b> (presenta el texto, autor y época), el <b>análisis</b> (explica las ideas principales usando vocabulario histórico como <i>soberanía</i>, <i>nación</i> o <i>súbdito</i>, propios del siglo XVIII y XIX) y la <b>reflexión</b> (tu valoración personal, apoyada en el texto). El objetivo de este mes es escribir un comentario de 15 oraciones bien organizadas.", "diagram": "COMENTARIO DE TEXTO<br><b>1. Introducción</b> → presenta el texto<br><b>2. Análisis</b> → explica las ideas clave<br><b>3. Reflexión</b> → tu opinión argumentada"}, {"type": "quiz", "kicker": "Ponte a prueba", "h": "Orden de un comentario", "q": "¿Qué parte del comentario de texto debe ir primero?", "opts": [{"t": "La reflexión personal", "ok": false}, {"t": "El análisis detallado de las ideas", "ok": false}, {"t": "La introducción, presentando el texto, su autor y su época", "ok": true}, {"t": "Una lista de conectores lógicos", "ok": false}], "okMsg": "Correcto. Sin presentar antes el texto, el lector no sabría de qué estás hablando.", "noMsg": "Recuerda el orden: primero se presenta el texto (introducción), después se analiza, y al final se reflexiona."}, {"type": "reflect", "kicker": "Manos a la obra", "h": "Escribe tu comentario guiado", "body": "Usando el texto que leíste la semana pasada, redacta tu propio comentario siguiendo la estructura de tres partes.", "prompt": "Escribe un comentario de texto de 15 oraciones: 3-4 para la introducción, 7-8 para el análisis (usa al menos dos palabras de vocabulario histórico) y 3-4 para la reflexión final."}]},
  "p6:Mar:3": {"title": "Conectores: el Pegamento de las Ideas", "steps": [{"type": "hook", "kicker": "Ideas sueltas, ideas unidas", "h": "¿Sabías que una sola palabra puede cambiar el sentido de todo un argumento?", "scenario": "Compara: «El texto defiende la libertad. Es difícil de aplicar» frente a «El texto defiende la libertad; <b>sin embargo</b>, es difícil de aplicar». La segunda frase muestra una relación que la primera no tenía.", "body": "Esta semana vas a dominar los <b>conectores lógicos</b>, esas palabras que dan coherencia y fuerza argumentativa a tu comentario de texto."}, {"type": "theory", "kicker": "Tipos de conectores", "h": "¿Qué función cumple cada conector?", "body": "Los conectores lógicos unen ideas mostrando su relación. <b>Por lo tanto</b> y <b>en consecuencia</b> indican una conclusión que se deriva de lo anterior. <b>Sin embargo</b> introduce un contraste u objeción. <b>Además</b> añade una idea nueva que refuerza la anterior. Usarlos bien hace que tu argumentación sea clara y convincente.", "diagram": "CONECTORES LÓGICOS<br><b>Consecuencia:</b> por lo tanto, en consecuencia<br><b>Contraste:</b> sin embargo<br><b>Adición:</b> además"}, {"type": "quiz", "kicker": "Ponte a prueba", "h": "Elige el conector correcto", "q": "«La Constitución de 1812 reconocía derechos importantes; ___, muchos de ellos tardaron años en aplicarse de verdad.» ¿Qué conector completa mejor la frase?", "opts": [{"t": "además", "ok": false}, {"t": "sin embargo", "ok": true}, {"t": "por lo tanto", "ok": false}, {"t": "en consecuencia", "ok": false}], "okMsg": "Muy bien. La frase muestra un contraste entre lo que decía la ley y lo que ocurrió en la realidad, por eso «sin embargo» es el conector correcto.", "noMsg": "Fíjate: la segunda parte de la frase contradice o matiza a la primera, así que necesitas un conector de <b>contraste</b>, no de consecuencia ni de adición."}, {"type": "reflect", "kicker": "Manos a la obra", "h": "Mejora tu comentario con conectores", "body": "Vuelve al comentario de texto que escribiste la semana pasada y revísalo.", "prompt": "Añade al menos cuatro conectores lógicos diferentes (uno de consecuencia, uno de contraste y dos de adición) a tu comentario de la semana anterior. Subraya cada conector que uses."}]},
  "p6:Mar:4": {"title": "La Espada que Nunca se Oxida", "steps": [{"type": "hook", "kicker": "Palabras que atraviesan los siglos", "h": "¿Qué palabras siguen teniendo poder 200 años después de ser escritas?", "scenario": "Has pasado el mes analizando un texto de 1812 que aún hoy podemos leer y comentar. Hay otro texto, mucho más antiguo, que sigue igual de vivo: la Biblia.", "body": "Esta semana terminas tu <b>comentario de texto histórico completo</b> y descubres que también la Palabra de Dios se describe como una herramienta viva y poderosa: <b>«la espada del Espíritu»</b> (Efesios 6:17)."}, {"type": "theory", "kicker": "Un arma que defiende la verdad", "h": "¿Por qué se llama a la Palabra de Dios «espada del Espíritu»?", "body": "Efesios 6:17 dice: <i>«Y tomad el yelmo de la salvación, y la espada del Espíritu, que es la palabra de Dios»</i>. Una espada sirve para defenderse y para cortar con claridad lo verdadero de lo falso. Igual que tú has aprendido a leer con atención un texto histórico para entender su verdadera intención, la Palabra de Dios nos ayuda a distinguir la verdad en medio de tantas voces. Comentar bien un texto y conocer bien la Palabra de Dios tienen algo en común: ambos exigen leer con atención y pensar con profundidad.", "diagram": "EFESIOS 6:17<br><b>Yelmo</b> → la salvación<br><b>Espada del Espíritu</b> → la Palabra de Dios<br><b>Función</b> → defender la verdad"}, {"type": "quiz", "kicker": "Ponte a prueba", "h": "El sentido del versículo", "q": "Según Efesios 6:17, ¿con qué se compara la Palabra de Dios?", "opts": [{"t": "Con un escudo que solo protege", "ok": false}, {"t": "Con una espada del Espíritu", "ok": true}, {"t": "Con un libro de historia antiguo", "ok": false}, {"t": "Con un mapa de un tesoro", "ok": false}], "okMsg": "Así es. La Palabra de Dios se compara con una espada del Espíritu: una herramienta viva para defender la verdad.", "noMsg": "Repasa el versículo: Efesios 6:17 la compara con una <b>espada del Espíritu</b>, no con un escudo, un libro de historia ni un mapa."}, {"type": "reflect", "kicker": "Entregable final", "h": "Completa tu comentario de texto histórico", "body": "Es momento de reunir todo lo trabajado este mes: la lectura atenta, la estructura en tres partes y los conectores lógicos.", "prompt": "Entrega tu <b>comentario de texto histórico completo</b> (introducción, análisis y reflexión, con conectores lógicos subrayados). Añade un párrafo final explicando con tus palabras qué relación encuentras entre «leer con atención un texto» y la idea de la Palabra de Dios como «espada del Espíritu» (Efesios 6:17)."}]},
  "p6:Abr:1": {"title": "1808: Una Nación se Levanta", "steps": [{"type": "hook", "kicker": "El principio de una guerra", "h": "¿Qué harías si un ejército extranjero entrara en tu país sin permiso?", "scenario": "En 1808, las tropas de Napoleón Bonaparte entraron en España con la excusa de pasar hacia Portugal. Lo que siguió fue una guerra que cambiaría la historia del país durante seis años.", "body": "Esta semana construyes una <b>línea de tiempo</b> de la Guerra de Independencia española (1808-1814): su inicio, sus momentos clave y su final."}, {"type": "theory", "kicker": "Una guerra de seis años", "h": "¿Cómo se desarrolló la Guerra de Independencia?", "body": "La <b>Guerra de Independencia</b> comenzó en 1808, cuando el pueblo español se levantó contra la ocupación de las tropas napoleónicas. Durante estos años se vivieron sitios de ciudades, resistencias heroicas y batallas decisivas, hasta que en 1814 las tropas francesas fueron finalmente expulsadas de España. Ordenar estos años en una línea de tiempo te ayuda a entender cómo unos hechos llevaron a otros.", "diagram": "GUERRA DE INDEPENDENCIA<br><b>1808</b> → inicio del conflicto contra Napoleón<br><b>1808-1814</b> → batallas y resistencia<br><b>1814</b> → fin de la ocupación francesa"}, {"type": "quiz", "kicker": "Ponte a prueba", "h": "Fechas clave", "q": "¿En qué año terminó la Guerra de Independencia española?", "opts": [{"t": "1808", "ok": false}, {"t": "1812", "ok": false}, {"t": "1814", "ok": true}, {"t": "1820", "ok": false}], "okMsg": "Correcto. La guerra se extendió de 1808 a 1814, cuando las tropas napoleónicas fueron finalmente expulsadas.", "noMsg": "Revisa la línea de tiempo: la guerra comenzó en 1808 y terminó en <b>1814</b>, después de seis años de conflicto."}, {"type": "reflect", "kicker": "Manos a la obra", "h": "Construye tu línea de tiempo", "body": "Investiga con ayuda de tu libro de texto o de tu profe los hechos principales de la Guerra de Independencia.", "prompt": "Dibuja una línea de tiempo desde 1808 hasta 1814. Marca al menos: el inicio del conflicto, dos batallas o sitios clave, y el año del fin de la guerra. Añade una frase breve bajo cada fecha."}]},
  "p6:Abr:2": {"title": "Cádiz, Cuna de Libertad", "steps": [{"type": "hook", "kicker": "Escribir leyes en tiempos de guerra", "h": "¿Puede nacer una idea de libertad en medio de una guerra?", "scenario": "Mientras la guerra contra Napoleón continuaba, en la ciudad de Cádiz un grupo de diputados se reunió para redactar un texto que cambiaría el futuro político de España: la Constitución de 1812.", "body": "Esta semana vuelves al preámbulo de la <b>Constitución de Cádiz de 1812</b>, pero ahora para descubrir los <b>valores fundamentales</b> que defendía."}, {"type": "theory", "kicker": "Los primeros derechos", "h": "¿Qué valores defendía la Constitución de 1812?", "body": "La Constitución de Cádiz de 1812 fue una de las primeras en reconocer <b>primeros derechos</b> para los ciudadanos, dentro del contexto de su época. En su preámbulo se defienden ideas como la <b>soberanía de la nación</b> y la necesidad de una ley común para todos. Leer su preámbulo con atención te permite identificar qué valores consideraban importantes los diputados que la escribieron.", "diagram": "CONSTITUCIÓN DE 1812<br><b>Dónde</b> → Cádiz<br><b>Cuándo</b> → en plena Guerra de Independencia<br><b>Qué defiende</b> → primeros derechos y soberanía nacional"}, {"type": "quiz", "kicker": "Ponte a prueba", "h": "Valores de la Constitución", "q": "¿Dónde y en qué contexto se redactó la Constitución de 1812?", "opts": [{"t": "En Madrid, en tiempos de paz total", "ok": false}, {"t": "En Cádiz, en plena Guerra de Independencia", "ok": true}, {"t": "En París, tras la victoria de Napoleón", "ok": false}, {"t": "En Barcelona, después de 1814", "ok": false}], "okMsg": "Exacto. La Constitución se redactó en Cádiz mientras España resistía la ocupación napoleónica.", "noMsg": "Recuerda: la Constitución de 1812 se escribió en <b>Cádiz</b>, precisamente en medio de la <b>Guerra de Independencia</b>."}, {"type": "reflect", "kicker": "Manos a la obra", "h": "Identifica los valores del preámbulo", "body": "Vuelve a leer el preámbulo de la Constitución de 1812 que ya trabajaste en marzo, ahora con la mirada puesta en su historia.", "prompt": "Escribe una lista de al menos tres valores fundamentales que defiende el preámbulo (por ejemplo, la soberanía de la nación) y explica con una frase por qué cada uno era importante en aquel momento histórico."}]},
  "p6:Abr:3": {"title": "Heroínas de la Resistencia", "steps": [{"type": "hook", "kicker": "Nombres que la historia recuerda", "h": "¿Qué se necesita para pasar a la historia como una persona valiente?", "scenario": "Entre los defensores de las ciudades españolas durante los años difíciles de resistencia se recuerdan nombres de mujeres que se mantuvieron firmes ante el peligro, como Agustina de Aragón o María Pita.", "body": "Esta semana investigas a una de estas dos figuras y elaboras un <b>perfil histórico</b> con datos concretos."}, {"type": "theory", "kicker": "Investigar como historiador", "h": "¿Cómo se elabora un buen perfil histórico?", "body": "Un perfil histórico riguroso no se basa en opiniones, sino en <b>datos verificables</b>: quién era la persona, cuándo vivió, qué hizo exactamente, y por qué se la recuerda. Al investigar a <b>Agustina de Aragón</b> o <b>María Pita</b>, tu tarea es reunir información concreta y ordenarla con claridad, igual que hiciste con el comentario de texto en marzo.", "diagram": "PERFIL HISTÓRICO<br><b>1.</b> Nombre y época<br><b>2-4.</b> Hechos concretos y verificables<br><b>5.</b> Por qué se la recuerda hoy"}, {"type": "quiz", "kicker": "Ponte a prueba", "h": "Rigor histórico", "q": "Al elaborar un perfil histórico de una figura como Agustina de Aragón o María Pita, ¿qué es lo más importante?", "opts": [{"t": "Inventar anécdotas que suenen interesantes", "ok": false}, {"t": "Basarse en datos verificables y ordenarlos con claridad", "ok": true}, {"t": "Copiar exactamente lo que dice una sola fuente sin revisar nada", "ok": false}, {"t": "Centrarse solo en su aspecto físico", "ok": false}], "okMsg": "Correcto. Un buen perfil histórico se apoya en datos verificables, no en invenciones.", "noMsg": "Recuerda: la clave de un perfil histórico riguroso es usar <b>datos verificables</b>, no anécdotas inventadas."}, {"type": "reflect", "kicker": "Manos a la obra", "h": "Elabora tu perfil de 5 datos", "body": "Elige a Agustina de Aragón o a María Pita e investiga sobre ella con ayuda de tu libro de texto o de tu profe.", "prompt": "Escribe un perfil de 5 datos sobre la figura que elijas: 1) quién era, 2) cuándo vivió, 3) qué papel tuvo en la resistencia, 4) un hecho concreto que se recuerde de ella, 5) por qué sigue siendo un ejemplo hoy."}]},
  "p6:Abr:4": {"title": "Una Palabra que No Cae con los Imperios", "steps": [{"type": "hook", "kicker": "Imperios que caen, palabras que permanecen", "h": "¿Qué queda cuando un gran imperio desaparece?", "scenario": "El imperio de Napoleón, que parecía imparable en 1808, terminó derrotado en pocos años. España resistió, la Constitución de Cádiz quedó escrita, y hoy, dos siglos después, seguimos hablando de aquellos hechos.", "body": "Esta semana entregas tu <b>trabajo final</b> sobre la Guerra de Independencia y la Constitución de 1812, y descubres un versículo que conecta con todo lo aprendido: <b>«la palabra del Dios nuestro permanece para siempre»</b> (Isaías 40:8)."}, {"type": "theory", "kicker": "Lo que permanece", "h": "¿Por qué dice Isaías que la Palabra de Dios permanece para siempre?", "body": "Isaías 40:8 dice: <i>«La palabra del Dios nuestro permanece para siempre»</i>. Este mes has visto cómo un imperio poderoso, el de Napoleón, cayó en pocos años, mientras que el pueblo que resistió y una Constitución escrita en medio de la guerra siguen siendo recordados dos siglos después. La Biblia enseña que, incluso cuando caen los imperios y cambian las naciones, la Palabra de Dios permanece firme, sin caducar nunca.", "diagram": "ISAÍAS 40:8<br><b>Imperios</b> → nacen y caen (como el de Napoleón)<br><b>Palabra de Dios</b> → permanece para siempre"}, {"type": "quiz", "kicker": "Ponte a prueba", "h": "El sentido del versículo", "q": "Según Isaías 40:8, ¿qué permanece para siempre aunque los imperios caigan?", "opts": [{"t": "El poder de los ejércitos", "ok": false}, {"t": "La palabra de Dios", "ok": true}, {"t": "Las fronteras de los países", "ok": false}, {"t": "Las riquezas de los reyes", "ok": false}], "okMsg": "Así es. Isaías 40:8 enseña que la Palabra de Dios permanece para siempre, aunque todo lo demás cambie o caiga.", "noMsg": "Repasa el versículo: lo que permanece para siempre según Isaías 40:8 es <b>la palabra de Dios</b>, no el poder militar ni las riquezas."}, {"type": "reflect", "kicker": "Entregable final", "h": "Completa tu trabajo final", "body": "Reúne todo lo investigado este mes: la línea de tiempo, los valores de la Constitución de 1812 y el perfil de la heroína elegida.", "prompt": "Entrega tu trabajo <b>«La Guerra de Independencia y la Constitución de 1812»</b>, incluyendo tu línea de tiempo, los valores de la Constitución y tu perfil de 5 datos. Añade un párrafo final explicando con tus palabras qué relación encuentras entre la caída del imperio de Napoleón y la idea de Isaías 40:8 de que «la palabra de Dios permanece para siempre»."}]},
  "p6:May:1": {"title": "Maletas al otro lado del mundo", "steps": [{"type": "hook", "kicker": "ESPAÑA VACÍA", "h": "¿Por qué en los años 60 medio pueblo se subió a un tren?", "scenario": "Imagina tu pueblo en 1960: la mitad de las familias hacen las maletas en la misma década.", "body": "En el siglo XX, millones de españoles dejaron sus pueblos y su país buscando trabajo y futuro. Fue uno de los movimientos migratorios más grandes de la historia de España: <b>del campo a la ciudad</b> y <b>de España a Europa</b>."}, {"type": "theory", "kicker": "DOS OLEADAS", "h": "La migración interior y la migración exterior", "body": "Durante el <b>franquismo</b> (años 50-70), España vivió dos grandes movimientos migratorios. El primero fue el <b>éxodo rural</b>: campesinos que dejaron el campo para trabajar en las fábricas de Madrid, Barcelona o Bilbao. El segundo fue la <b>emigración exterior</b>: cientos de miles de españoles viajaron a países como <b>Alemania, Francia y Suiza</b>, y también a <b>América Latina</b> (Argentina, Venezuela), buscando trabajo, ya que en España escaseaba el empleo y los salarios eran muy bajos.", "diagram": "AÑOS 50-70 EN ESPAÑA<br><b>Campo</b> → <b>Ciudad</b> (éxodo rural)<br><b>España</b> → <b>Alemania, Suiza, Francia</b> (trabajo industrial)<br><b>España</b> → <b>América Latina</b> (lazos históricos)<br>Motivo común: <b>buscar trabajo y una vida mejor</b>"}, {"type": "quiz", "kicker": "PONTE A PRUEBA", "h": "¿A dónde emigraron muchos españoles?", "q": "¿Cuáles fueron dos destinos principales de la emigración española del siglo XX?", "opts": [{"t": "Alemania y Argentina", "ok": true}, {"t": "Japón y Australia", "ok": false}, {"t": "Rusia y China", "ok": false}, {"t": "Canadá y Egipto", "ok": false}], "okMsg": "¡Correcto! Alemania (Europa) y Argentina (América Latina) recibieron a muchos españoles que buscaban trabajo.", "noMsg": "No es esa. Recuerda: los españoles emigraron sobre todo a países europeos industrializados y a países de América Latina."}, {"type": "reflect", "kicker": "INVESTIGA", "h": "Tu turno: sé un pequeño historiador", "body": "Vas a investigar sobre la emigración española del siglo XX usando lo que has aprendido hoy.", "prompt": "Escribe un texto breve (6-8 líneas) explicando qué es la emigración interior y la emigración exterior. Cita al menos dos países que recibieron emigrantes españoles y dos motivos por los que la gente decidía marcharse."}]},
  "p6:May:2": {"title": "Un emigrante en mi familia", "steps": [{"type": "hook", "kicker": "HISTORIA FAMILIAR", "h": "¿Hay un emigrante escondido en tu árbol genealógico?", "scenario": "Puede que un abuelo, una tía abuela o un vecino de tus padres se marchara alguna vez a otro país o a otra ciudad para trabajar.", "body": "Esta semana la protagonista es <b>tu propia familia</b>. Vas a convertirte en periodista e investigador para descubrir si alguien cercano a ti vivió una historia de migración."}, {"type": "theory", "kicker": "LA MEMORIA VIVE EN LAS PERSONAS", "h": "¿Por qué es importante entrevistar a la generación mayor?", "body": "La Historia no solo está en los libros: también vive en la <b>memoria de las personas mayores</b>. Entrevistar a un familiar nos permite entender la emigración desde dentro, con datos reales: qué sintieron, qué dejaron atrás y qué encontraron. Para hacer una buena entrevista necesitas preguntas claras, como: ¿A dónde te fuiste (o se fue tu familiar)? ¿Por qué motivo? ¿Cómo era la vida allí? ¿Echabas de menos algo de España?", "diagram": "UNA BUENA ENTREVISTA TIENE:<br><b>Destino</b>: ¿a dónde fue?<br><b>Motivo</b>: ¿por qué se marchó?<br><b>Experiencia</b>: ¿cómo fue la vida allí?<br><b>Sentimientos</b>: ¿qué se echaba de menos?"}, {"type": "quiz", "kicker": "PONTE A PRUEBA", "h": "¿Cuál es una buena pregunta de entrevista?", "q": "¿Cuál de estas es una buena pregunta para entrevistar sobre migración?", "opts": [{"t": "¿Por qué motivo decidiste emigrar?", "ok": true}, {"t": "¿Qué día es hoy?", "ok": false}, {"t": "¿Te gusta el fútbol?", "ok": false}, {"t": "¿Cuántos años tienes ahora mismo?", "ok": false}], "okMsg": "Exacto, esa pregunta va directa al motivo de la migración, algo clave para tu investigación.", "noMsg": "No es la mejor opción. Busca la pregunta que realmente indaga en la experiencia migratoria."}, {"type": "reflect", "kicker": "ENTREVISTA", "h": "Manos a la obra: tu reportaje familiar", "body": "Busca a un familiar (o al familiar de algún vecino o amigo) que haya vivido una emigración, aunque sea de un pueblo a una ciudad.", "prompt": "Entrevista a un familiar (o investiga si no encuentras a nadie disponible) y recoge sus respuestas a estas 4 preguntas: ¿A dónde emigró? ¿Por qué motivo? ¿Cómo era la vida allí? ¿Qué es lo que más echaba de menos de España? Si no encuentras a nadie cercano, investiga el caso de una persona famosa que haya emigrado."}]},
  "p6:May:3": {"title": "España, tierra de acogida", "steps": [{"type": "hook", "kicker": "ESPAÑA HOY", "h": "¿Sabías que España ha cambiado de bando?", "scenario": "El país que durante el siglo XX enviaba a su gente a trabajar fuera, hoy recibe a millones de personas de todo el mundo.", "body": "Hoy España ya no es solo un país de <b>emigrantes</b>, sino también un país de <b>inmigrantes</b>: personas que llegan de otros lugares buscando lo mismo que buscaban los españoles hace décadas: trabajo y una vida mejor."}, {"type": "theory", "kicker": "¿DE DÓNDE VIENEN?", "h": "Los principales orígenes de la inmigración en España", "body": "En España viven personas procedentes de muchísimos países, aunque hay algunos orígenes especialmente numerosos: <b>Marruecos</b> (por cercanía geográfica y lazos históricos), <b>Rumanía</b> (dentro de la Unión Europea), y <b>Colombia, Venezuela y Ecuador</b> u otros países de <b>América Latina</b> (por el idioma común y los lazos culturales). Cada comunidad aporta su propia cultura, gastronomía, música y tradiciones, enriqueciendo la sociedad española.", "diagram": "¿QUIÉN VIVE HOY EN ESPAÑA?<br><b>Marruecos</b> → cercanía y lazos históricos<br><b>Rumanía</b> → Unión Europea<br><b>Colombia, Venezuela, Ecuador</b> → idioma y cultura compartidos<br>Cada país aporta algo único a España"}, {"type": "quiz", "kicker": "PONTE A PRUEBA", "h": "¿Por qué muchas personas de América Latina emigran a España?", "q": "¿Cuál de estos es un motivo real por el que muchas personas de países latinoamericanos emigran a España?", "opts": [{"t": "Comparten el idioma español y lazos culturales", "ok": true}, {"t": "España está más cerca de América que Europa", "ok": false}, {"t": "En América Latina está prohibido trabajar", "ok": false}, {"t": "España no permite la inmigración de otros continentes", "ok": false}], "okMsg": "Correcto. El idioma común y los vínculos históricos facilitan la llegada de personas de países latinoamericanos.", "noMsg": "No es correcta. Piensa en qué comparten España y los países de América Latina."}, {"type": "reflect", "kicker": "INVESTIGA", "h": "Tu propia investigación", "body": "Vas a investigar sobre 5 países de origen de la inmigración en España y qué aporta cada comunidad a la cultura española.", "prompt": "Haz una lista de 5 países de origen de personas inmigrantes en España (puedes usar los mencionados hoy u otros que investigues) y escribe, para cada uno, una aportación cultural, gastronómica o social que esa comunidad ha traído a España."}]},
  "p6:May:4": {"title": "Amar al extranjero", "steps": [{"type": "hook", "kicker": "LA VOZ DE LA BIBLIA", "h": "¿Qué dice la Biblia sobre tratar al extranjero?", "scenario": "Después de conocer las historias de emigrantes españoles y de inmigrantes que llegan hoy a España, toca preguntarse cómo deberíamos tratar a quien llega de fuera.", "body": "En el libro de <b>Deuteronomio</b>, Dios da instrucciones muy claras al pueblo de Israel sobre cómo tratar a los extranjeros, recordándoles que ellos también fueron extranjeros alguna vez."}, {"type": "theory", "kicker": "DEUTERONOMIO 10:19", "h": "\"Amad, pues, al extranjero\"", "body": "El versículo de esta semana dice: <i>\"Amad, pues, al extranjero; porque extranjeros fuisteis en la tierra de Egipto\"</i> (Deuteronomio 10:19). Dios pide a su pueblo que trate bien a quien llega de fuera, porque ellos mismos habían sido extranjeros en Egipto y sabían lo que se siente. Esta idea conecta directamente con lo que hemos estudiado: los españoles fueron emigrantes en otros países, y hoy España recibe a personas de otros países. La <b>hospitalidad</b> no es solo una norma bíblica, es también un principio de justicia y empatía.", "diagram": "DEUTERONOMIO 10:19<br>\"Amad al extranjero...<br>porque extranjeros fuisteis en Egipto\"<br><b>Memoria</b> + <b>Empatía</b> = <b>Hospitalidad</b>"}, {"type": "quiz", "kicker": "PONTE A PRUEBA", "h": "¿Por qué debía Israel amar al extranjero?", "q": "Según Deuteronomio 10:19, ¿por qué debía el pueblo de Israel amar al extranjero?", "opts": [{"t": "Porque ellos mismos habían sido extranjeros en Egipto", "ok": true}, {"t": "Porque los extranjeros eran más ricos", "ok": false}, {"t": "Porque Egipto se lo ordenó por ley", "ok": false}, {"t": "Porque no había suficiente gente en Israel", "ok": false}], "okMsg": "Así es. La memoria de haber sido extranjeros debía llevarlos a tratar bien a quienes llegaban de fuera.", "noMsg": "No es correcta. Repasa el versículo: la razón tiene que ver con su propia historia en Egipto."}, {"type": "reflect", "kicker": "TRABAJO FINAL", "h": "Migración en España: histórica y actual", "body": "Es el momento de reunir todo lo aprendido este mes en un trabajo final, uniendo la investigación histórica, tu entrevista familiar, la inmigración actual y la reflexión bíblica.", "prompt": "Elabora tu trabajo final 'Migración en España: histórica y actual' incluyendo: 1) un resumen de la emigración española del siglo XX, 2) lo que descubriste en tu entrevista familiar, 3) tu lista de países de origen de la inmigración actual, y 4) una reflexión personal de 4-5 líneas sobre cómo aplicarías el mandato de Deuteronomio 10:19 de 'amar al extranjero' en tu colegio o barrio."}]},
  "p6:Jun:1": {"title": "Lázaro, el niño que sobrevivió con ingenio", "steps": [{"type": "hook", "kicker": "RUMBO A LA ESO", "h": "¿Listo para tu primer clásico de la literatura española?", "scenario": "El próximo curso empiezas la ESO, y allí te pedirán leer y analizar obras literarias más complejas.", "body": "Vas a leer los primeros episodios de <b>El Lazarillo de Tormes</b>, una de las obras más famosas de la literatura española, en una versión adaptada para que puedas disfrutarla y entenderla bien."}, {"type": "theory", "kicker": "UN CLÁSICO ADAPTADO", "h": "¿Qué es El Lazarillo de Tormes?", "body": "El <b>Lazarillo de Tormes</b> es una novela española del siglo XVI que cuenta la vida de <b>Lázaro</b>, un niño pobre que tiene que servir a varios amos (entre ellos un ciego avaro) para sobrevivir. Es considerada la primera <b>novela picaresca</b> de la literatura española: un género que cuenta las aventuras de un protagonista humilde que usa el ingenio para salir adelante. Leer sus primeros episodios te ayudará a entender el vocabulario y los recursos literarios que encontrarás en la ESO.", "diagram": "EL LAZARILLO DE TORMES<br><b>Protagonista</b>: Lázaro, niño pobre<br><b>Género</b>: novela picaresca<br><b>Recurso</b>: ingenio para sobrevivir<br><b>Importancia</b>: primer clásico que leerás en profundidad"}, {"type": "quiz", "kicker": "PONTE A PRUEBA", "h": "¿Qué es una novela picaresca?", "q": "¿Qué es una 'novela picaresca'?", "opts": [{"t": "Un relato sobre un protagonista humilde que sobrevive gracias a su ingenio", "ok": true}, {"t": "Un poema sobre el amor cortés", "ok": false}, {"t": "Una obra de teatro sobre reyes y nobles", "ok": false}, {"t": "Un cuento de hadas medieval", "ok": false}], "okMsg": "Correcto. La novela picaresca narra las aventuras de un protagonista pobre que se las ingenia para sobrevivir.", "noMsg": "No es correcta. Piensa en el tipo de protagonista y la situación que vive Lázaro."}, {"type": "reflect", "kicker": "LECTURA", "h": "Tu resumen de lector", "body": "Vas a leer los tres primeros episodios (tratados) del Lazarillo de Tormes en su versión adaptada y después vas a resumirlos con tus propias palabras.", "prompt": "Lee los tres primeros episodios adaptados del Lazarillo de Tormes y escribe un resumen de exactamente 8 oraciones, explicando quién es Lázaro, con quién vive y qué situaciones importantes le ocurren con el ciego."}]},
  "p6:Jun:2": {"title": "Defiende tu idea: el ensayo breve", "steps": [{"type": "hook", "kicker": "TU PRIMER ENSAYO", "h": "¿Puedes defender una idea con argumentos, como hacen los mayores?", "scenario": "En la ESO ya no bastará con contar lo que sabes: tendrás que defender una opinión con argumentos sólidos, como hacen los periodistas y los historiadores.", "body": "Esta semana vas a escribir tu primer <b>ensayo breve</b>, un tipo de texto en el que se defiende una <b>tesis</b> (una idea principal) con argumentos, eligiendo un tema libre de la historia de España."}, {"type": "theory", "kicker": "TESIS Y ARGUMENTOS", "h": "¿Cómo se construye un ensayo breve?", "body": "Un <b>ensayo</b> es un texto en el que expones y defiendes tu opinión sobre un tema. Para escribir uno bueno necesitas: una <b>tesis</b> (la idea principal que quieres defender, por ejemplo: 'la llegada del ferrocarril cambió España'), <b>argumentos</b> (razones y datos que apoyan tu tesis) y una <b>conclusión</b> que cierre tu idea. En la ESO te pedirán ensayos como este continuamente, así que cuanto antes practiques, mejor.", "diagram": "ESTRUCTURA DEL ENSAYO BREVE<br><b>Tesis</b>: tu idea principal<br><b>Argumentos</b>: razones y datos que la apoyan<br><b>Conclusión</b>: cierre que refuerza tu tesis<br>Extensión: 15-18 oraciones"}, {"type": "quiz", "kicker": "PONTE A PRUEBA", "h": "¿Qué es la tesis de un ensayo?", "q": "¿Qué es la 'tesis' de un ensayo?", "opts": [{"t": "La idea principal que el autor defiende a lo largo del texto", "ok": true}, {"t": "El título del ensayo", "ok": false}, {"t": "La última frase del texto", "ok": false}, {"t": "Un resumen de la biografía del autor", "ok": false}], "okMsg": "Exacto. La tesis es la idea central que defiendes con tus argumentos.", "noMsg": "No es correcta. La tesis es la idea principal que vertebra todo el ensayo."}, {"type": "reflect", "kicker": "ESCRITURA", "h": "Escribe tu ensayo", "body": "Elige un tema libre relacionado con la historia de España (por ejemplo: los Reyes Católicos, la Guerra Civil, la Transición o el descubrimiento de América) y defiende una idea sobre él.", "prompt": "Escribe un ensayo breve de entre 15 y 18 oraciones sobre un tema libre de historia española. Incluye una tesis clara al principio, al menos tres argumentos que la sostengan y una conclusión final."}]},
  "p6:Jun:3": {"title": "Palabras con peso: mi glosario académico", "steps": [{"type": "hook", "kicker": "PALABRAS PARA LA ESO", "h": "¿Cuántas palabras 'raras' aparecen ya en tus libros de texto?", "scenario": "Cuando empieces la ESO te vas a encontrar palabras nuevas y complejas en cada asignatura. Cuanto más amplio sea tu vocabulario, más fácil te resultará entender los textos.", "body": "Esta semana el diccionario será tu mejor herramienta: vas a buscar <b>10 palabras académicas</b> y aprender a usarlas correctamente en tus propias frases."}, {"type": "theory", "kicker": "EL DICCIONARIO COMO HERRAMIENTA", "h": "¿Por qué es tan importante el vocabulario académico?", "body": "El <b>vocabulario académico</b> son esas palabras que aparecen en textos de estudio, exámenes y ensayos, pero que casi nunca se usan al hablar con los amigos: por ejemplo, <i>analizar</i>, <i>contexto</i>, <i>argumento</i>, <i>consecuencia</i> o <i>síntesis</i>. Usar el diccionario para comprobar el significado exacto de una palabra, y no solo intuirlo, es un hábito clave para tener éxito en la ESO. Buscar una palabra, leer su definición completa y luego construir una frase propia con ella es la mejor forma de aprenderla de verdad.", "diagram": "CÓMO APRENDER UNA PALABRA NUEVA<br>1. <b>Buscarla</b> en el diccionario<br>2. <b>Leer</b> su definición completa<br>3. <b>Escribir</b> una frase propia con ella<br>Resultado: vocabulario académico para la ESO"}, {"type": "quiz", "kicker": "PONTE A PRUEBA", "h": "¿Qué haces después de buscar una palabra?", "q": "¿Cuál es el mejor paso después de buscar una palabra en el diccionario?", "opts": [{"t": "Escribir una frase propia usando esa palabra correctamente", "ok": true}, {"t": "Olvidarla en cuanto cierres el diccionario", "ok": false}, {"t": "Copiar la definición sin leerla", "ok": false}, {"t": "Buscar otra palabra distinta sin terminar la primera", "ok": false}], "okMsg": "Correcto. Escribir tu propia frase es lo que fija de verdad el significado de una palabra nueva.", "noMsg": "No es correcta. El paso clave es usar la palabra en una frase propia."}, {"type": "reflect", "kicker": "GLOSARIO", "h": "Tu glosario personal", "body": "Busca en el diccionario 10 palabras que consideres 'académicas' (de las que aparecen en tus libros de texto pero no usas al hablar cada día).", "prompt": "Busca 10 palabras académicas en el diccionario, escribe su definición breve con tus propias palabras y construye una frase original con cada una de ellas. Este será el comienzo de tu glosario personal."}]},
  "p6:Jun:4": {"title": "Sabiduría para el nuevo curso", "steps": [{"type": "hook", "kicker": "SABIDURÍA PARA EL CAMINO", "h": "¿Qué es más importante que tener muchas cosas?", "scenario": "Terminas 6º de Primaria y empiezas una nueva etapa: la ESO. Es un buen momento para preguntarte qué es lo más valioso que puedes llevarte contigo.", "body": "El libro de <b>Proverbios</b> tiene una respuesta clara sobre qué deberíamos valorar por encima de todas las cosas al empezar cualquier etapa nueva de la vida."}, {"type": "theory", "kicker": "PROVERBIOS 4:7", "h": "\"Adquiere sabiduría\"", "body": "El versículo de esta semana dice: <i>\"Adquiere sabiduría y sobre todas tus posesiones adquiere inteligencia\"</i> (Proverbios 4:7). Este versículo enseña que la <b>sabiduría</b> vale más que cualquier posesión material. Todo lo que has practicado este mes —leer con atención el Lazarillo, defender ideas con argumentos en tu ensayo, ampliar tu vocabulario— es, en el fondo, un modo de <b>adquirir sabiduría</b> para prepararte para la ESO y para la vida.", "diagram": "PROVERBIOS 4:7<br>\"Adquiere sabiduría...<br>sobre todas tus posesiones adquiere inteligencia\"<br>Leer + Argumentar + Vocabulario = <b>Sabiduría para la ESO</b>"}, {"type": "quiz", "kicker": "PONTE A PRUEBA", "h": "¿Qué se debe adquirir por encima de todo?", "q": "Según Proverbios 4:7, ¿qué se debe adquirir por encima de todas las posesiones?", "opts": [{"t": "Sabiduría e inteligencia", "ok": true}, {"t": "Dinero y riquezas", "ok": false}, {"t": "Fama y popularidad", "ok": false}, {"t": "Ropa y objetos nuevos", "ok": false}], "okMsg": "Correcto. El versículo pone la sabiduría y la inteligencia por encima de cualquier posesión material.", "noMsg": "No es correcta. Repasa el versículo: habla de algo que vale más que las posesiones materiales."}, {"type": "reflect", "kicker": "TRABAJO FINAL", "h": "Ensayo de historia española + glosario personal", "body": "Es el momento de reunir el trabajo de todo el mes: tu ensayo sobre historia española y tu glosario de vocabulario académico, además de una reflexión final sobre la sabiduría.", "prompt": "Entrega tu trabajo final compuesto por: 1) tu ensayo breve de historia española (15-18 oraciones), 2) tu glosario personal con las 10 palabras académicas y sus frases, y 3) una reflexión de 4-5 líneas explicando qué significa para ti 'adquirir sabiduría' (Proverbios 4:7) al terminar 6º de Primaria y empezar la ESO."}]},
  "p6:Jul:1": {"title": "El gran ensayo: mi herencia y mi responsabilidad", "steps": [{"type": "hook", "kicker": "Proyecto final · Sesión 1", "h": "¿Qué te ha dado España para que tú se lo devuelvas al mundo?", "scenario": "Es julio. Llevas seis años en Primaria y este es tu último proyecto antes de la ESO. Un profesor de instituto te pregunta: <b>\"¿Qué historia cargas sobre los hombros y qué vas a hacer con ella?\"</b>", "body": "Este mes cierras toda la etapa de Educación Primaria con un <b>proyecto final de nivel ESO</b>: un ensayo, un mapa mental y una presentación oral. Hoy empiezas por lo más importante: pensar con tu propia cabeza qué herencia histórica recibiste y qué responsabilidad te da vivir en España como cristiano."}, {"type": "theory", "kicker": "Cómo se construye un ensayo de nivel ESO", "h": "Herencia + argumento + compromiso personal", "body": "Un <b>ensayo</b> no es un resumen: es tu opinión razonada, apoyada en hechos históricos que ya conoces (Reyes Católicos, Imperio, Ilustración, Constitución de 1812, la España global de hoy). Tu ensayo de <b>18 a 20 oraciones</b> debe tener tres partes: 1) <b>Introducción</b>: qué entiendes por \"herencia histórica\". 2) <b>Desarrollo</b>: 2 o 3 ejemplos concretos de la historia de España que forman esa herencia (lengua, leyes, fe, encuentro de culturas). 3) <b>Cierre</b>: qué responsabilidad personal te da esa herencia como cristiano español de tu generación.", "diagram": "ENSAYO (18-20 oraciones)<br><b>Introducción</b> → qué es la herencia<br><b>Desarrollo</b> → 2-3 ejemplos históricos<br><b>Cierre</b> → mi responsabilidad hoy"}, {"type": "quiz", "kicker": "Comprueba antes de escribir", "h": "¿Qué distingue a un ensayo de un simple resumen?", "q": "¿Cuál es la diferencia clave entre un ensayo y un resumen histórico?", "opts": [{"t": "El ensayo defiende una opinión propia argumentada con hechos", "ok": true}, {"t": "El ensayo solo enumera fechas y reyes en orden", "ok": false}, {"t": "El ensayo no necesita ejemplos históricos reales", "ok": false}, {"t": "El ensayo debe copiar literalmente el libro de texto", "ok": false}], "okMsg": "Correcto. Un ensayo argumenta con tu propia voz, apoyada en hechos reales. Eso es pensamiento de nivel ESO.", "noMsg": "No exactamente. Un ensayo no es una lista de datos: es tu argumento personal, sostenido con ejemplos históricos verdaderos."}, {"type": "reflect", "kicker": "Tarea de la semana", "h": "Escribe tu ensayo de cierre de etapa", "body": "Escribe tu ensayo titulado <b>\"Qué herencia histórica tiene España y qué responsabilidad me da\"</b>, con 18 a 20 oraciones, siguiendo la estructura de introducción, desarrollo y cierre. Usa al menos dos hechos históricos concretos que hayas estudiado este curso.", "prompt": "Escribe aquí tu ensayo completo (18-20 oraciones): explica qué herencia histórica recibiste de España y qué responsabilidad personal te da como cristiano de tu generación."}]},
  "p6:Jul:2": {"title": "Un mapa para un año entero", "steps": [{"type": "hook", "kicker": "Proyecto final · Sesión 2", "h": "¿Cabe un año entero de historia en una sola hoja?", "scenario": "Tienes tu ensayo escrito. Ahora tu profesor te reta: <b>\"Dibuja todo lo que aprendiste este año en un solo gráfico, sin usar ni una frase completa\".</b>", "body": "Esta semana construyes el <b>mapa mental del año</b>: un solo gráfico que conecte <b>historia, geografía y lengua</b> de 6º de Primaria. No es un resumen escrito, es un mapa visual: palabras clave, flechas y ramas que muestran cómo se relaciona todo lo que estudiaste."}, {"type": "theory", "kicker": "Cómo organizar un mapa mental de síntesis", "h": "Un centro, tres ramas, ideas clave", "body": "Coloca en el centro la idea <b>\"España: historia, geografía y lengua\"</b>. De ahí salen tres ramas principales: <b>Historia</b> (decadencia del s. XVII, Ilustración y Borbones, Guerra de Independencia, Constitución de 1812, España global), <b>Geografía</b> (relieve, regiones, el lugar de España en el mundo) y <b>Lengua</b> (el español, el Quijote, la Navidad en la literatura española). Cada rama se divide en 2 o 3 palabras clave, no frases largas.", "diagram": "CENTRO: España — historia, geografía, lengua<br><b>Rama Historia</b> → Ilustración, 1812, globalización<br><b>Rama Geografía</b> → relieve, regiones, mundo<br><b>Rama Lengua</b> → Quijote, Navidad literaria, español"}, {"type": "quiz", "kicker": "Antes de dibujar", "h": "¿Qué NO debe tener un buen mapa mental?", "q": "¿Qué elemento es incorrecto en un mapa mental de síntesis?", "opts": [{"t": "Frases completas y párrafos largos en cada rama", "ok": true}, {"t": "Palabras clave cortas conectadas con flechas", "ok": false}, {"t": "Un centro claro con tres ramas principales", "ok": false}, {"t": "Colores o símbolos que ayudan a recordar", "ok": false}], "okMsg": "Exacto. Un mapa mental usa palabras clave, no párrafos. La brevedad es lo que lo hace útil como apoyo visual.", "noMsg": "Revisa de nuevo: lo incorrecto es escribir frases completas y largas, porque un mapa mental debe ser breve y visual."}, {"type": "reflect", "kicker": "Tarea de la semana", "h": "Diseña tu mapa mental del año", "body": "Dibuja (a mano o en digital) tu mapa mental con el centro <b>\"España: historia, geografía y lengua\"</b> y sus tres ramas. Este mapa será tu apoyo visual la próxima semana durante tu presentación oral de 8 minutos.", "prompt": "Describe aquí, rama por rama, el contenido de tu mapa mental: qué palabras clave pondrías en Historia, en Geografía y en Lengua."}]},
  "p6:Jul:3": {"title": "Tu voz, tu turno: presentación final", "steps": [{"type": "hook", "kicker": "Proyecto final · Sesión 3", "h": "Ocho minutos para mostrar seis años de aprendizaje", "scenario": "Es el gran día. Con tu ensayo y tu mapa mental en la mano, te pones de pie frente a tu clase, tu familia o tu iglesia. Tienes <b>8 minutos</b> para contar quién eres como español y como cristiano.", "body": "Esta semana practicas y realizas tu <b>presentación oral de 8 minutos</b>, usando el mapa mental como apoyo visual. No se trata de memorizar palabra por palabra, sino de <b>argumentar con tu propia voz</b>, como se espera ya en la ESO."}, {"type": "theory", "kicker": "Cómo argumentar en público a nivel ESO", "h": "Estructura, ritmo y contacto visual", "body": "Una buena presentación de 8 minutos se organiza así: <b>1-2 min</b> de introducción (quién eres y qué vas a contar), <b>5 min</b> de desarrollo apoyado en tu mapa mental (historia, geografía, lengua y tu ensayo), y <b>1-2 min</b> de conclusión personal (tu responsabilidad como cristiano español). Habla despacio, mira a tu público y usa el mapa mental como guion visual, no como texto para leer.", "diagram": "PRESENTACIÓN (8 min)<br><b>Intro</b> (1-2 min) → quién soy<br><b>Desarrollo</b> (5 min) → mapa mental + ensayo<br><b>Conclusión</b> (1-2 min) → mi responsabilidad"}, {"type": "quiz", "kicker": "Antes de presentar", "h": "¿Cuál es el mejor uso del mapa mental durante la presentación?", "q": "¿Cómo debes usar tu mapa mental mientras hablas en público?", "opts": [{"t": "Como guía visual de apoyo, sin leerlo palabra por palabra", "ok": true}, {"t": "Como un texto que lees en voz alta de principio a fin", "ok": false}, {"t": "Escondiéndolo para que nadie lo vea", "ok": false}, {"t": "Solo mostrándolo al final, sin mencionarlo antes", "ok": false}], "okMsg": "Correcto. El mapa mental es tu apoyo visual: te ayuda a recordar el orden de ideas sin depender de leer un texto.", "noMsg": "No es lo ideal. El mapa mental funciona mejor como guía visual de apoyo, no como un texto para leer literalmente."}, {"type": "reflect", "kicker": "Tarea de la semana", "h": "Prepara y ensaya tu presentación oral", "body": "Practica tu presentación de 8 minutos usando tu mapa mental como apoyo. Ensáyala en voz alta al menos dos veces antes de presentarla ante tu clase, tu familia o tu grupo de iglesia.", "prompt": "Escribe el guion breve de tu presentación: qué dirás en la introducción, qué tres ideas del mapa mental desarrollarás y cómo cerrarás con tu responsabilidad personal."}]},
  "p6:Jul:4": {"title": "Gracias, Señor, por seis años de camino", "steps": [{"type": "hook", "kicker": "Proyecto final · Sesión 4 · Clausura", "h": "Seis años de Primaria terminan hoy. ¿Qué le dices a Dios?", "scenario": "Has presentado tu ensayo, tu mapa mental y tu exposición oral. Este es el último paso: no un examen, sino una <b>oración de clausura</b> de toda tu etapa de Educación Primaria.", "body": "Hoy cierras seis años completos de estudio: de 1º a 6º de Primaria. Es momento de agradecer a Dios por la <b>historia</b>, la <b>lengua</b> y la <b>tierra</b> que te dio, y de recordar que todo lo que hiciste este año —el ensayo, el mapa, la presentación— lo hiciste, en el fondo, para Él."}, {"type": "theory", "kicker": "El versículo de cierre de etapa", "h": "\"Como para el Señor\"", "body": "El versículo que corona este proyecto final es <b>Colosenses 3:23</b>: <b>\"Todo lo que hacéis, hacedlo de corazón, como para el Señor.\"</b> Durante seis años estudiaste historia, geografía, lengua y fe. Este versículo te recuerda que el propósito último de todo ese esfuerzo no era solo una nota, sino <b>hacerlo de corazón para Dios</b>, con excelencia y gratitud.", "diagram": "6 años de Primaria<br>Ensayo + Mapa mental + Presentación<br>↓<br>\"Todo lo que hacéis, hacedlo de corazón, como para el Señor\" (Col 3:23)"}, {"type": "quiz", "kicker": "Antes de orar", "h": "¿Qué enseña Colosenses 3:23 sobre tu trabajo escolar?", "q": "Según Colosenses 3:23, ¿para quién debe hacerse en el fondo todo tu esfuerzo?", "opts": [{"t": "Para el Señor, con el corazón, más allá de la nota o el aplauso", "ok": true}, {"t": "Únicamente para conseguir la mejor calificación", "ok": false}, {"t": "Solo para impresionar a los demás compañeros", "ok": false}, {"t": "Para terminar cuanto antes, sin importar cómo", "ok": false}], "okMsg": "Así es. Colosenses 3:23 te recuerda que tu esfuerzo de seis años tiene un destinatario último: Dios mismo.", "noMsg": "Vuelve a leer el versículo: la clave es hacerlo \"de corazón, como para el Señor\", no solo por la nota o el reconocimiento."}, {"type": "reflect", "kicker": "Tarea final de la etapa", "h": "Escribe tu oración de clausura de Primaria", "body": "Escribe una oración de clausura para cerrar tus seis años de Educación Primaria. Agradece a Dios por la historia de España, por la lengua española y por la tierra que te dio, y pídele sabiduría para la nueva etapa de la ESO que comienza.", "prompt": "Escribe tu oración de clausura: agradece a Dios por la historia, la lengua y la tierra, menciona algo que aprendiste en estos seis años de Primaria, y pide su guía para la ESO."}]},
});
